import {useCallback, useState} from 'react'
import {useRunAutomation} from './use-run-automation'
import type {Automation} from '../types/automations-payload'
import type {Trigger} from '@github-ui/automation-form/types'

interface UseRunAutomationActionArgs {
  owner: string
  repo: string
  automation: Automation | undefined
  triggerDefinitions: Trigger[]
  onSuccess?: () => void
  onError?: (message: string) => void
  /** When true, running is blocked (e.g. the repository has no commits) and handleRunClick is a no-op. */
  disabled?: boolean
}

/**
 * Determines whether to show the run dialog or immediately trigger an ad hoc run.
 * - No triggers → run immediately with event 'manual'
 * - Only 'interval' trigger → run immediately with event 'interval'
 * - Multiple/other triggers → open dialog for user selection
 *
 * Callers must pass triggerDefinitions from useTriggers() to ensure the trigger
 * list is always available and consistent across all call sites.
 */
export function useRunAutomationAction({
  owner,
  repo,
  automation,
  triggerDefinitions,
  onSuccess,
  onError,
  disabled = false,
}: UseRunAutomationActionArgs) {
  const [isRunDialogOpen, setIsRunDialogOpen] = useState(false)
  const {
    mutate: runAutomation,
    isPending,
    error,
    reset,
  } = useRunAutomation({
    owner,
    repo,
    automationId: automation?.id ?? '',
  })

  const handleRunClick = useCallback(() => {
    if (disabled || !automation?.id) return
    reset()
    const triggerKeys = Object.keys(automation.triggers ?? {})
    const shouldSkipDialog = triggerKeys.length === 0 || (triggerKeys.length === 1 && triggerKeys[0] === 'interval')
    if (shouldSkipDialog) {
      const event = triggerKeys.length === 0 ? 'manual' : 'interval'
      runAutomation(
        {event},
        {
          onSuccess,
          onError: (err: Error) => onError?.(err.message),
        },
      )
    } else {
      setIsRunDialogOpen(true)
    }
  }, [automation, runAutomation, onSuccess, onError, reset, disabled])

  return {
    isRunDialogOpen,
    setIsRunDialogOpen,
    handleRunClick,
    triggerDefinitions,
    isPending,
    error,
    resetError: reset,
    runAutomation,
  }
}
