import {useCallback, useMemo} from 'react'
import type {Action} from '@github-ui/action-bar'
import {ActionBar} from '@github-ui/action-bar'
import type {ActiveTab} from '@github-ui/agent-sessions/types/filter-types'
import type {FilterOption, SortDirection} from '@github-ui/agent-sessions/utils/filter-utils'
import {
  getStatusOptionsForTab,
  getConsolidatedStatusOptionsForTab,
  selectedAgentsAllowQueued,
  TYPE_OPTIONS,
} from '@github-ui/agent-sessions/utils/filter-utils'
import {SortFilter} from '@github-ui/agent-sessions/components/filters/SortFilter'
import {MultiSelectFilter} from '@github-ui/agent-sessions/components/filters/MultiSelectFilter'
import {AgentMultiSelectFilter} from '@github-ui/agent-sessions/components/filters/AgentMultiSelectFilter'
import {CreatorSelectPanel} from './CreatorSelectPanel'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import styles from '../RepoTaskList.module.css'

export interface FilterActionBarProps {
  activeTab: ActiveTab
  owner: string
  repo: string
  sortDirection?: SortDirection
  onSortChange?: (direction: SortDirection) => void
  creatorOptions?: FilterOption[]
  selectedCreators?: string[]
  onCreatorChange?: (creators: string[]) => void
  selectedStatuses?: string[]
  onStatusChange?: (statuses: string[]) => void
  agentOptions?: FilterOption[]
  selectedAgents?: string[]
  onAgentChange?: (agents: string[]) => void
  selectedTypes?: string[]
  onTypeChange?: (types: string[]) => void
}

export function FilterActionBar({
  activeTab,
  owner,
  repo,
  sortDirection,
  onSortChange,
  creatorOptions,
  selectedCreators,
  onCreatorChange,
  selectedStatuses,
  onStatusChange,
  agentOptions,
  selectedAgents,
  onAgentChange,
  selectedTypes,
  onTypeChange,
}: FilterActionBarProps) {
  const hasFilters = Boolean(onSortChange && onStatusChange && onAgentChange)
  const consolidatedFiltersEnabled = isFeatureEnabled('copilot_mission_control_filters_followups')
  const statusOptions = consolidatedFiltersEnabled
    ? getConsolidatedStatusOptionsForTab(activeTab, selectedTypes || [], selectedAgents || [], agentOptions || [])
    : getStatusOptionsForTab(activeTab)

  // When type or agent filter changes to exclude cloud, clear "queued" from selected statuses
  const handleTypeChangeWithCleanup = useCallback(
    (types: string[]) => {
      if (onTypeChange) onTypeChange(types)
      if (consolidatedFiltersEnabled && onStatusChange && selectedStatuses?.includes('queued')) {
        const typeAllowsQueued = types.length === 0 || types.includes('cloud')
        if (!typeAllowsQueued || !selectedAgentsAllowQueued(selectedAgents || [], agentOptions || [])) {
          onStatusChange(selectedStatuses.filter(s => s !== 'queued'))
        }
      }
    },
    [consolidatedFiltersEnabled, onTypeChange, onStatusChange, selectedStatuses, selectedAgents, agentOptions],
  )

  const handleAgentChangeWithCleanup = useCallback(
    (agents: string[]) => {
      if (onAgentChange) onAgentChange(agents)
      if (consolidatedFiltersEnabled && onStatusChange && selectedStatuses?.includes('queued')) {
        if (!selectedAgentsAllowQueued(agents, agentOptions || [])) {
          onStatusChange(selectedStatuses.filter(s => s !== 'queued'))
        }
      }
    },
    [consolidatedFiltersEnabled, onAgentChange, onStatusChange, selectedStatuses, agentOptions],
  )

  const actions: Action[] = useMemo(() => {
    if (!hasFilters) return []

    const filterActions: Action[] = []

    if (onCreatorChange) {
      filterActions.push({
        key: 'creator',
        render: (isOverflowMenu: boolean) => (
          <CreatorSelectPanel
            creatorOptions={creatorOptions || []}
            selectedCreators={selectedCreators || []}
            onCreatorChange={onCreatorChange}
            owner={owner}
            repo={repo}
            nested={isOverflowMenu}
          />
        ),
      })
    }

    filterActions.push({
      key: 'status',
      render: (isOverflowMenu: boolean) => (
        <MultiSelectFilter
          label="Status"
          selected={selectedStatuses || []}
          options={statusOptions}
          onSelectionChange={onStatusChange as (values: string[]) => void}
          testId="status-filter-button"
          className={!isOverflowMenu ? styles.filterButton : undefined}
          nested={isOverflowMenu}
        />
      ),
    })

    if (onTypeChange) {
      filterActions.push({
        key: 'type',
        render: (isOverflowMenu: boolean) => (
          <MultiSelectFilter
            label="Type"
            selected={selectedTypes || []}
            options={TYPE_OPTIONS}
            onSelectionChange={handleTypeChangeWithCleanup}
            testId="type-filter-button"
            className={!isOverflowMenu ? styles.filterButton : undefined}
            nested={isOverflowMenu}
          />
        ),
      })
    }

    if ((agentOptions || []).length > 1) {
      filterActions.push({
        key: 'agent',
        render: (isOverflowMenu: boolean) => (
          <AgentMultiSelectFilter
            agentOptions={agentOptions || []}
            selectedAgents={selectedAgents || []}
            onAgentChange={handleAgentChangeWithCleanup}
            className={!isOverflowMenu ? styles.filterButton : undefined}
            nested={isOverflowMenu}
          />
        ),
      })
    }

    filterActions.push({
      key: 'sort',
      render: (isOverflowMenu: boolean) => (
        <SortFilter
          sortDirection={sortDirection || 'newest'}
          onSortChange={onSortChange as (direction: SortDirection) => void}
          className={!isOverflowMenu ? styles.filterButton : undefined}
          nested={isOverflowMenu}
        />
      ),
    })

    return filterActions
  }, [
    hasFilters,
    onCreatorChange,
    creatorOptions,
    selectedCreators,
    owner,
    repo,
    selectedStatuses,
    statusOptions,
    onStatusChange,
    handleTypeChangeWithCleanup,
    onTypeChange,
    selectedTypes,
    agentOptions,
    selectedAgents,
    handleAgentChangeWithCleanup,
    sortDirection,
    onSortChange,
  ])

  if (!hasFilters) return null

  return <ActionBar label="Task filters" actions={actions} />
}
