import {useId, useState} from 'react'
import {Banner, Button, Checkbox, FormControl, Heading, TextInput} from '@primer/react'
import {ModelPicker, AUTO_MODEL_ID} from '@github-ui/agent-sessions/components/task-view/ModelPicker'
import {QuotaBanner} from '@github-ui/agent-sessions/components/task-view/QuotaBanner'
import {useCopilotLicenseType} from '@github-ui/agent-sessions/hooks/use-copilot-license-type'
import {useAgentQuotaSnapshot} from '@github-ui/agent-sessions/hooks/use-agent-quota-snapshot'
import {EntitlementProvider, useEntitlement} from '@github-ui/copilot-chat/components/quota/EntitlementContext'

import styles from './AutomationForm.module.css'
import {TriggerInput, INTERVAL_ANCHOR_FIELDS} from './TriggerInput'
import {ToolsInput} from './ToolsInput'
import {useToolGroups} from './use-tool-groups'
import {useTriggers} from './use-triggers'
import type {SelectedTrigger, Trigger} from './types'
import type {ToolGroup} from './tool-definitions'

export type AutomationFormData = {
  name: string
  description: string
  prompt: string
  triggers: SelectedTrigger[]
  requireActorWritePermission: boolean
  tools: string[]
  model: string
}

/** A blocking notice rendered as a warning banner that also disables submission. */
export type SubmitDisabledNotice = {
  title: string
  description: string
}

/**
 * Notice shown when the target repository has no commits. Automations resolve a
 * base ref to run against, which an empty (non-git-initialized) repository lacks,
 * so creating, saving, running, or enabling one is blocked until the repository
 * has a commit. Reused across the form banner and the automations list/detail
 * surfaces, so the copy is intentionally surface-agnostic.
 */
export const EMPTY_REPO_NOTICE: SubmitDisabledNotice = {
  title: 'Repository has no commits yet',
  description:
    'Automations need a base branch to run, so they’re unavailable until the repository has at least one commit.',
}

type AutomationFormProps = {
  /** Optional heading displayed above the form. Omit when embedding in a modal with its own title. */
  heading?: string
  /** Optional subtitle displayed below the heading. */
  subtitle?: string
  /** Called when the user cancels. */
  onCancel: () => void
  /** Called with trimmed form data when the user submits; may be async. */
  onSubmit: (data: AutomationFormData) => void | Promise<void>
  /** Label for the submit button. Defaults to "Create automation". */
  submitLabel?: string
  /** Pre-fill the form for editing an existing automation. */
  initialData?: Partial<AutomationFormData>
  /** Hide the name field when name is managed externally (e.g. editable title). */
  hideNameField?: boolean
  /** Pre-loaded trigger definitions to avoid fetching. */
  initialTriggers?: Trigger[]
  /** Pre-loaded tool groups to avoid fetching. */
  initialToolGroups?: ToolGroup[]
  /** Org-level read-access trigger policy; false locks the write-permission checkbox. */
  orgAllowReadAccessTriggers?: boolean | null
  /** Repo-level read-access trigger policy; false locks the write-permission checkbox. */
  repoAllowReadAccessTriggers?: boolean
  /** When set, renders a warning banner and disables submission (e.g. empty repository). */
  submitDisabledNotice?: SubmitDisabledNotice
}

/**
 * Converts a name to a filename slug: lowercase, spaces/underscores to hyphens,
 * strips non-alphanumeric characters, and collapses repeated hyphens.
 */
export function slugify(name: string): string {
  return name
    .toLowerCase()
    .replace(/[\s_]+/g, '-')
    .replace(/[^a-z0-9-]/g, '')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
}

/** Fields that should be serialized as a single string rather than an array. */
const SCALAR_TRIGGER_FIELDS = new Set(['query'])

/**
 * Builds the `on:` trigger block as a plain object for YAML serialization.
 * Omits optional fields that have no values. Interval anchor fields
 * (day_of_week, hour_utc) are serialized as a single numeric value rather
 * than a string array.
 */
export function buildTriggerObject(triggers: SelectedTrigger[]): Record<string, Record<string, unknown>> | null {
  if (triggers.length === 0) return null

  const on: Record<string, Record<string, unknown>> = {}
  for (const trigger of triggers) {
    const entry: Record<string, unknown> = {}
    for (const [fieldName, values] of Object.entries(trigger.fieldValues)) {
      const trimmed = values.map(v => v.trim()).filter(v => v.length > 0)
      if (trimmed.length === 0) continue
      // Interval anchor fields serialize as scalar integers, omitted when
      // the parsed value isn't a valid int rather than submitted as garbage.
      if (trigger.name === 'interval' && (INTERVAL_ANCHOR_FIELDS as readonly string[]).includes(fieldName)) {
        const parsed = Number(trimmed[0])
        if (Number.isInteger(parsed)) {
          entry[fieldName] = parsed
        }
        continue
      }
      entry[fieldName] = SCALAR_TRIGGER_FIELDS.has(fieldName) ? trimmed[0] : trimmed
    }
    if (Object.keys(entry).length > 0) {
      on[trigger.name] = entry
    }
  }
  return Object.keys(on).length > 0 ? on : null
}

/**
 * Returns true when all required trigger fields have at least one value.
 */
function areTriggerFieldsValid(triggers: SelectedTrigger[], definitions: Trigger[]): boolean {
  for (const trigger of triggers) {
    const def = definitions.find(d => d.name === trigger.name)
    if (!def) return false
    for (const field of def.fields) {
      if (field.required) {
        const values = trigger.fieldValues[field.name] ?? []
        if (values.length === 0) return false
      }
    }
  }
  return true
}

type ModelPickerWithEntitlementProps = {
  selectedModelId: string | undefined
  onUpdateModel: (modelId: string) => void
}

function ModelPickerWithEntitlement({selectedModelId, onUpdateModel}: ModelPickerWithEntitlementProps) {
  const {tokenBasedBillingEnabled} = useEntitlement()

  return (
    <ModelPicker
      selectedModelId={selectedModelId}
      onUpdateModel={onUpdateModel}
      isTokenBasedBillingEnabled={tokenBasedBillingEnabled}
    />
  )
}

/**
 * Reusable automation form with name, triggers, tools, and prompt fields.
 */
export function AutomationForm({
  heading,
  subtitle,
  onCancel,
  onSubmit,
  submitLabel = 'Create automation',
  initialData,
  hideNameField,
  initialTriggers,
  initialToolGroups,
  orgAllowReadAccessTriggers,
  repoAllowReadAccessTriggers,
  submitDisabledNotice,
}: AutomationFormProps) {
  const [name, setName] = useState(initialData?.name ?? '')
  const [description] = useState(initialData?.description ?? '')
  const [prompt, setPrompt] = useState(initialData?.prompt ?? '')
  const [selectedTriggers, setSelectedTriggers] = useState<SelectedTrigger[]>(initialData?.triggers ?? [])
  const [requireActorWritePermission, setRequireActorWritePermission] = useState(
    initialData?.requireActorWritePermission ?? true,
  )
  const [selectedTools, setSelectedTools] = useState<string[]>(initialData?.tools ?? [])
  const [selectedModelId, setSelectedModelId] = useState<string | undefined>(initialData?.model)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const licenseType = useCopilotLicenseType()
  const requireActorWritePermissionId = useId()
  const promptId = useId()
  const {toolGroups, loading: toolGroupsLoading} = useToolGroups(initialToolGroups)
  const {triggers: triggerDefinitions, loading: triggersLoading} = useTriggers(initialTriggers)

  const slug = slugify(name.trim())

  const showRequireActorWritePermission = selectedTriggers.some(trigger => trigger.name !== 'interval')
  const {data: agentQuotaSnapshot} = useAgentQuotaSnapshot({enabled: true})
  const hasIssueTriggers = selectedTriggers.some(trigger => trigger.name === 'issues')
  const hasPRTriggers = selectedTriggers.some(trigger => trigger.name.startsWith('pull_request'))
  const writeAccessLabel =
    hasIssueTriggers && hasPRTriggers
      ? 'Only run automations for issues and pull requests where a user has write access to the repository'
      : hasPRTriggers
        ? 'Only run automations for pull requests where a user has write access to the repository'
        : hasIssueTriggers
          ? 'Only run automations for issues where a user has write access to the repository'
          : 'Only run automations for events triggered by users with write access to the repository'

  // Read actors blocked by a higher-level policy → lock the moot checkbox and name the blocking layer.
  const orgBlocksReadActors = orgAllowReadAccessTriggers === false
  const repoBlocksReadActors = repoAllowReadAccessTriggers === false
  const readActorsDisabledByPolicy = orgBlocksReadActors || repoBlocksReadActors
  const readActorsPolicyCaption =
    orgBlocksReadActors && repoBlocksReadActors
      ? 'This is locked by your organization and repository settings'
      : orgBlocksReadActors
        ? 'This is locked by your organization settings'
        : 'This is locked by your repository settings'
  const isValid =
    (hideNameField || slug.length > 0) &&
    prompt.trim().length > 0 &&
    areTriggerFieldsValid(selectedTriggers, triggerDefinitions)

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    if (!isValid || submitDisabledNotice || isSubmitting) return
    setIsSubmitting(true)
    try {
      await onSubmit({
        name: name.trim(),
        description: description.trim(),
        prompt: prompt.trim(),
        triggers: selectedTriggers,
        requireActorWritePermission: showRequireActorWritePermission ? requireActorWritePermission : false,
        tools: selectedTools,
        model: selectedModelId || AUTO_MODEL_ID,
      })
      // Success: caller navigates away, so stay disabled until this view unmounts.
    } catch {
      // Only re-enable on failure so the user can retry; the caller surfaces the error.
      setIsSubmitting(false)
    }
  }

  return (
    <form className={styles.form} onSubmit={handleSubmit}>
      {heading && (
        <div className={styles.headingGroup}>
          <Heading as="h2" className={styles.heading}>
            {heading}
          </Heading>
          {subtitle && <div className={styles.subtitle}>{subtitle}</div>}
        </div>
      )}
      {submitDisabledNotice && (
        <Banner variant="warning" title={submitDisabledNotice.title}>
          {submitDisabledNotice.description}
        </Banner>
      )}
      <QuotaBanner agentQuotaSnapshot={agentQuotaSnapshot} />
      {!hideNameField && (
        <FormControl required>
          <FormControl.Label>Name</FormControl.Label>
          <TextInput placeholder="Enter a short name" value={name} onChange={e => setName(e.target.value)} block />
        </FormControl>
      )}
      <TriggerInput
        value={selectedTriggers}
        onChange={setSelectedTriggers}
        triggers={triggerDefinitions}
        loading={triggersLoading}
        footer={
          showRequireActorWritePermission ? (
            <FormControl id={requireActorWritePermissionId} disabled={readActorsDisabledByPolicy}>
              <FormControl.Label>{writeAccessLabel}</FormControl.Label>
              <FormControl.Caption>
                {readActorsDisabledByPolicy
                  ? readActorsPolicyCaption
                  : 'When checked, the automation will only run if the user triggering the event has write access to the repository. This does not apply to the "Schedule" trigger.'}
              </FormControl.Caption>
              <Checkbox
                checked={requireActorWritePermission}
                onChange={e => setRequireActorWritePermission(e.target.checked)}
              />
            </FormControl>
          ) : undefined
        }
      />
      <FormControl required>
        <FormControl.Label htmlFor={promptId}>Prompt</FormControl.Label>
        <div className={styles.promptFieldWrapper}>
          <textarea
            id={promptId}
            className={styles.promptTextarea}
            placeholder="Describe what the agent should do"
            value={prompt}
            onChange={e => setPrompt(e.target.value)}
            rows={6}
            required
          />
          <div className={styles.promptToolbar}>
            <EntitlementProvider initialLicenseType={licenseType}>
              <ModelPickerWithEntitlement selectedModelId={selectedModelId} onUpdateModel={setSelectedModelId} />
            </EntitlementProvider>
          </div>
        </div>
      </FormControl>
      <ToolsInput
        value={selectedTools}
        onChange={setSelectedTools}
        toolGroups={toolGroups}
        loading={toolGroupsLoading}
        suggestionContext={{name, description, prompt}}
      />
      <div className={styles.actions}>
        <Button type="button" onClick={onCancel}>
          Cancel
        </Button>
        <Button
          variant="primary"
          type="submit"
          loading={isSubmitting}
          disabled={!isValid || Boolean(submitDisabledNotice) || isSubmitting}
        >
          {submitLabel}
        </Button>
      </div>
    </form>
  )
}
