import {useCAPIQuery} from '@github-ui/agent-sessions/hooks/useCAPIQuery'
import {fetchCAPI} from '@github-ui/agent-sessions/utils/fetch-capi'
import type {Automation} from '../types/automations-payload'

async function fetchAutomations(owner: string, repo: string): Promise<Automation[]> {
  const response = await fetchCAPI({path: `/agents/repos/${owner}/${repo}/automations`})
  const data: Automation[] = await response.json()
  return data
}

export function useAutomations(owner: string, repo: string, initialData?: Automation[], enabled: boolean = true) {
  const {data, isLoading, isError} = useCAPIQuery({
    queryKey: ['automations', owner, repo],
    queryFn: () => fetchAutomations(owner, repo),
    initialData,
    enabled,
  })

  return {
    automations: data ?? [],
    isLoading,
    isError,
  }
}
