/**
 * Type definitions and permission mappings for the automation tool catalog.
 *
 * Tool groups are fetched at runtime from /agents/automations/tools.
 * See useToolGroups.ts for the data fetching hook.
 *
 * See: https://github.com/github/github-mcp-server/blob/main/README.md#tools
 * See: https://github.com/github/copilot-mission-control/issues/2954
 */

/** Permission scope for a tool, returned by /agents/automations/tools. */
export type ToolScope = 'read' | 'write'

export interface ToolDefinition {
  id: string
  name: string
  description: string
  /** Whether the tool only reads (`read`) or can also modify state (`write`). */
  scope: ToolScope
}

export interface ToolGroup {
  id: string
  name: string
  tools: ToolDefinition[]
}

/**
 * Tool group IDs the picker exposes. Filters both the picker menu and the
 * "Suggest tools" model catalog. `TOOL_GROUP_ICON_MAP` is typed against this.
 */
export const SELECTABLE_TOOL_GROUP_IDS = [
  'issues',
  'pull-requests',
  'coding',
  'general',
  'repos',
  'actions',
  'code-security',
  'labels',
] as const

export type SelectableToolGroupId = (typeof SELECTABLE_TOOL_GROUP_IDS)[number]

export function isSelectableToolGroup(groupId: string): groupId is SelectableToolGroupId {
  return (SELECTABLE_TOOL_GROUP_IDS as readonly string[]).includes(groupId)
}
