import {Fragment} from 'react'
import {Heading, IconButton} from '@primer/react'
import {ArrowLeftIcon, PlusIcon} from '@primer/octicons-react'
import {SidebarSection} from '@github-ui/pacer/SidebarNavigation'
import {useLayoutContext} from '@github-ui/pacer/Layout/layout-context'
import {useLocation} from '@github-ui/react-router'
import {useNavigate, useSearchParams} from '@github-ui/use-navigate'
import type {Repository} from '@github-ui/current-repository'
import type {UITask} from '@github-ui/agent-sessions/types/task'
import {
  getTaskSecondaryText,
  groupTasksByUpdatedAt,
  TaskBucketHeader,
  TaskListEntry,
} from '@github-ui/agent-sessions/components/TaskList'
import type {TaskBucket} from '@github-ui/agent-sessions/components/TaskList'
import {TaskActionProviders} from '@github-ui/agent-sessions/components/task-list/TaskActionProviders'
import {ArchiveErrorBanner} from '@github-ui/agent-sessions/components/ArchiveErrorBanner'
import {NewRepoAgentTaskButton} from '@github-ui/new-repo-agent-task-button/NewRepoAgentTaskButton'
import {useRepoTasks} from '../hooks/use-repo-tasks'
import {useAutomationTasks} from '../hooks/use-automation-tasks'
import {getTaskUrl, getTaskUrlAliases} from '../utils/url-helpers'
import styles from './TaskSidebar.module.css'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useSidebarAgentFilter} from '@github-ui/agent-sessions/contexts/SidebarAgentFilterContext'
import {useAutomation} from '../hooks/use-automation'
import {NudgeCard} from '@github-ui/agent-sessions/components/nudges/NudgeCard'
import {useNudge} from '@github-ui/agent-sessions/hooks/use-nudge'

export interface TaskSidebarProps {
  repository: Repository
  currentUserId?: number
  /**
   * The current user's login, used to determine if tasks should be filtered.
   * When provided, tasks are filtered to the current user by default (when no author param).
   */
  currentUserLogin?: string
  /**
   * Whether the current user can push changes (i.e. write) to the repo.
   */
  currentUserCanPush?: boolean
  /**
   * ID to apply to the sidebar heading for accessibility labeling.
   */
  labelId?: string
}

/**
 * TaskSidebar component showing task list for the current repository.
 * Defaults to showing only the current user's sessions. Only shows all sessions
 * when the author query parameter is explicitly set to a different user or '*'.
 */
export function TaskSidebar({
  repository,
  currentUserId,
  currentUserLogin,
  currentUserCanPush,
  labelId,
}: TaskSidebarProps) {
  const {automationId, isAgentFilterActive} = useSidebarAgentFilter()
  const {automation, isLoading: isAutomationLoading} = useAutomation({
    owner: repository.ownerLogin,
    repo: repository.name,
    automationId: isAgentFilterActive ? (automationId ?? undefined) : undefined,
  })
  const {
    activeNudge,
    dismiss: dismissNudge,
    dismissAll: dismissAllNudges,
    trackImpression,
    trackClick,
    goToNext,
    goToPrev,
    totalCount,
  } = useNudge('agents_tab_below_input')

  const [searchParams] = useSearchParams()
  const authorFilter = searchParams.get('author')
  const typeFilter = searchParams.get('type')
  const isFilteredByCurrentUser = currentUserLogin
    ? authorFilter === currentUserLogin || (authorFilter === null && typeFilter === null)
    : false

  let heading: string
  if (isAgentFilterActive) {
    heading = automation?.name ?? (isAutomationLoading ? '' : 'All sessions')
  } else if (isFilteredByCurrentUser) {
    heading = 'Created by me'
  } else {
    heading = 'All sessions'
  }

  return (
    <>
      <SidebarContent
        repository={repository}
        currentUserId={currentUserId}
        currentUserLogin={currentUserLogin}
        currentUserCanPush={currentUserCanPush}
        labelId={labelId}
        heading={heading}
      />
      {isFeatureEnabled('copilot_mc_nudges') && activeNudge && (
        <div className={styles.sidebarNudge}>
          <NudgeCard
            nudge={activeNudge}
            onDismiss={dismissNudge}
            onDismissAll={dismissAllNudges}
            onImpression={trackImpression}
            onClick={trackClick}
            onNext={goToNext}
            onPrev={goToPrev}
            totalCount={totalCount}
            compact
          />
        </div>
      )}
    </>
  )
}

interface SidebarContentProps {
  repository: Repository
  currentUserId?: number
  currentUserLogin?: string
  currentUserCanPush?: boolean
  labelId?: string
  heading: string
}

function SidebarContent({
  repository,
  currentUserId,
  currentUserLogin,
  currentUserCanPush,
  labelId,
  heading,
}: SidebarContentProps) {
  const owner = repository.ownerLogin
  const repo = repository.name
  const repoId = repository.id
  const navigate = useNavigate()
  const {sidebarExpanded, toggleSidebar} = useLayoutContext()
  const [searchParams] = useSearchParams()
  const {isAgentFilterActive, automationId} = useSidebarAgentFilter()
  const {automation} = useAutomation({
    owner,
    repo,
    automationId: isAgentFilterActive ? (automationId ?? undefined) : undefined,
  })

  // Create a copy of searchParams without session_id - it should not persist when navigating between tasks
  const filteredParams = new URLSearchParams(searchParams)
  filteredParams.delete('session_id')
  const searchParamsString = filteredParams.toString()

  // Get author and type filters from query params. Outside code review mode, filter by currentUserId
  // when author matches currentUserLogin, or when neither author nor type is set (the default "my sessions" view).
  // In code review mode, tasks are always scoped to currentUserId, so the author param is effectively ignored.
  const authorFilter = searchParams.get('author')
  const typeFilter = searchParams.get('type')
  const taskType = isFeatureEnabled('copilot_mission_control_code_review_tab') ? (typeFilter ?? undefined) : undefined
  const isCodeReviewMode = taskType === 'review'
  const isFilteredByCurrentUser = currentUserLogin
    ? authorFilter === currentUserLogin || (authorFilter === null && typeFilter === null)
    : false

  const isCurrentUserAutomationOwner =
    isAgentFilterActive && currentUserId != null && automation?.created_by?.id === currentUserId
  const automationHref =
    isAgentFilterActive && automationId
      ? `/${owner}/${repo}/agents/automations/${encodeURIComponent(automationId)}`
      : null

  // When agent filter is active, don't filter by current user — show all tasks for that agent
  let effectiveUserId: number | undefined
  if (isAgentFilterActive) {
    effectiveUserId = undefined
  } else if (isFilteredByCurrentUser || isCodeReviewMode) {
    effectiveUserId = currentUserId
  }

  // When agent filter is active, use the dedicated automation endpoint;
  // otherwise use the standard repo tasks endpoint.
  const {
    tasks: automationTasks,
    isLoading: isAutomationLoading,
    isError: isAutomationError,
  } = useAutomationTasks({
    automationId: isAgentFilterActive ? (automationId ?? undefined) : undefined,
  })

  const {
    tasks: repoTasks,
    queryKey,
    isLoading: isRepoLoading,
    isError: isRepoError,
    isPRLoading,
  } = useRepoTasks({
    owner,
    repo,
    repoId,
    creatorIds: effectiveUserId ? [effectiveUserId] : undefined,
    fetchArchivedTasks: false,
    taskType,
    enabled: !isAgentFilterActive,
  })

  const tasks = isAgentFilterActive ? automationTasks : repoTasks
  const isLoading = isAgentFilterActive ? isAutomationLoading : isRepoLoading
  const isError = isAgentFilterActive ? isAutomationError : isRepoError

  const handleTaskClick = () => {
    if (sidebarExpanded) {
      toggleSidebar()
    }
  }

  const groupedTasks = groupTasksByUpdatedAt(tasks)

  const showLoading = isLoading || (!isAgentFilterActive && isCodeReviewMode && !!isPRLoading)

  return (
    <>
      <div className={styles.header}>
        <div className={styles.headingGroup}>
          {isCurrentUserAutomationOwner && automationHref && (
            <IconButton
              as="a"
              href={automationHref}
              icon={ArrowLeftIcon}
              variant="invisible"
              size="small"
              className={styles.backButton}
              aria-label={`Back to ${automation?.name ?? 'automation'}`}
              onClick={(e: React.MouseEvent) => {
                // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
                if (e.metaKey || e.ctrlKey || e.shiftKey || e.button === 1) return
                e.preventDefault()
                navigate(automationHref)
              }}
            />
          )}
          <Heading as="h2" id={labelId} className={styles.heading}>
            {heading}
          </Heading>
        </div>
        {currentUserCanPush && (
          <NewRepoAgentTaskButton
            repository={repository}
            currentUserId={currentUserId}
            currentUserLogin={currentUserLogin}
            eventType="repo_agents_sidebar"
            size="small"
            label="New session"
            icon={PlusIcon}
            variant="invisible"
            taskListQueryKey={queryKey}
          />
        )}
      </div>
      {isError ? (
        <div className={styles.errorMessage}>Failed to load sessions</div>
      ) : (
        <SidebarTaskList
          tasks={tasks}
          groupedTasks={groupedTasks}
          showLoading={showLoading}
          owner={owner}
          repo={repo}
          currentUserId={currentUserId}
          isCodeReviewMode={isCodeReviewMode}
          searchParamsString={searchParamsString}
          onTaskClick={handleTaskClick}
        />
      )}
    </>
  )
}

interface SidebarTaskListProps {
  tasks: UITask[]
  groupedTasks: Array<TaskBucket<UITask>>
  showLoading: boolean
  owner: string
  repo: string
  currentUserId?: number
  isCodeReviewMode: boolean
  searchParamsString: string
  onTaskClick: () => void
}

function SidebarTaskList({
  tasks,
  groupedTasks,
  showLoading,
  owner,
  repo,
  currentUserId,
  isCodeReviewMode,
  searchParamsString,
  onTaskClick,
}: SidebarTaskListProps) {
  const location = useLocation()

  return (
    <TaskActionProviders>
      <ArchiveErrorBanner />
      {!showLoading && tasks.length === 0 ? (
        <div className={styles.emptyMessage}>No active sessions</div>
      ) : (
        <SidebarSection isLoading={showLoading} isEmpty={showLoading || tasks.length === 0}>
          {groupedTasks.map(bucket => (
            <Fragment key={bucket.label}>
              <TaskBucketHeader label={bucket.label} />
              {bucket.tasks.map(task => {
                const nwo = `${owner}/${repo}`
                const basePath = getTaskUrl(nwo, task) ?? ''
                const taskUrl = searchParamsString ? `${basePath}?${searchParamsString}` : basePath
                const aliases = getTaskUrlAliases(nwo, task)
                const isSelected = aliases.includes(location.pathname)

                return (
                  <TaskListEntry
                    key={task.resource_id}
                    task={task}
                    href={taskUrl}
                    isSelected={isSelected}
                    secondaryText={getTaskSecondaryText(task)}
                    onTaskClick={onTaskClick}
                    reloadDocument={false}
                    repoOwner={owner}
                    repoName={repo}
                    currentUserIsOwner={currentUserId === task.creator_id}
                    preferPullTitle={isCodeReviewMode}
                    formatAsReview={isCodeReviewMode}
                  />
                )
              })}
            </Fragment>
          ))}
        </SidebarSection>
      )}
    </TaskActionProviders>
  )
}
