import {setTitle} from '@github-ui/document-metadata'
import {useCurrentRepository} from '@github-ui/current-repository'
import {useParams} from '@github-ui/react-router'
import {ActionList, ActionMenu, Heading, IconButton, TextInput} from '@primer/react'
import {KebabHorizontalIcon, PencilIcon, TrashIcon} from '@primer/octicons-react'
import {useNavigate} from '@github-ui/use-navigate'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {editAutomationRoute} from '../../routes/automations-route'
import {useAutomation} from '../../hooks/use-automation'
import {useUpdateAutomation} from '../../hooks/use-update-automation'
import {AutomationForm, EMPTY_REPO_NOTICE} from '@github-ui/automation-form'
import type {AutomationFormData} from '@github-ui/automation-form'
import type {AutomationDetail} from '../../types/automations-payload'
import type {SelectedTrigger} from '@github-ui/automation-form/types'
import {DeleteAutomationDialog} from './DeleteAutomationDialog'
import {ActiveLimitReachedBanner, isActiveLimitReachedError} from './ActiveLimitReachedBanner'

import styles from './RepoAgentsView.module.css'
import editStyles from './EditAutomationView.module.css'

function automationToFormData(automation: AutomationDetail): Partial<AutomationFormData> {
  const triggers: SelectedTrigger[] = Object.entries(automation.triggers ?? {}).map(([name, trigger]) => {
    const fieldValues: Record<string, string[]> = {}
    if (trigger.types) fieldValues.types = trigger.types
    if (trigger.workflows) fieldValues.workflows = trigger.workflows
    if (trigger.conclusions) fieldValues.conclusions = trigger.conclusions
    if (trigger.paths) fieldValues.paths = trigger.paths
    if (trigger.query) fieldValues.query = [trigger.query]
    if (trigger.hour_utc != null) {
      fieldValues.hour_utc = [String(trigger.hour_utc)]
    }
    if (trigger.day_of_week != null) {
      fieldValues.day_of_week = [String(trigger.day_of_week)]
    }
    return {name, fieldValues}
  })

  return {
    name: automation.name,
    description: automation.description,
    prompt: automation.prompt,
    triggers,
    requireActorWritePermission: automation.require_actor_write_permission ?? false,
    tools: automation.tools ?? [],
    model: automation.model,
  }
}

export function EditAutomationView() {
  const {data: payload} = useRouteQuery(editAutomationRoute, 'mainQuery')
  const repository = useCurrentRepository()
  const navigate = useNavigate()
  const {automationID} = useParams<{automationID?: string}>()

  if (!automationID) {
    throw new Error('Missing automationID route parameter')
  }

  const {automation} = useAutomation({
    owner: repository.ownerLogin,
    repo: repository.name,
    automationId: automationID,
    initialData: payload.automation,
  })
  const backHref = `/${repository.ownerLogin}/${repository.name}/agents/automations/${encodeURIComponent(automationID)}`
  const {mutateAsync: updateAutomation} = useUpdateAutomation({
    owner: repository.ownerLogin,
    repo: repository.name,
    automationId: automationID,
  })
  const [name, setName] = useState(automation?.name ?? '')
  const [isEditingName, setIsEditingName] = useState(false)
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
  const [cappedOnEnable, setCappedOnEnable] = useState(false)
  const nameInputRef = useRef<HTMLInputElement>(null)

  if (automation && name === '' && automation.name !== '') {
    setName(automation.name)
  }

  useEffect(() => {
    if (automation) {
      setTitle(`Edit ${automation.name} · Automations · ${repository.nameWithOwner}`)
    }
  }, [automation, repository.nameWithOwner])

  useEffect(() => {
    if (isEditingName) {
      nameInputRef.current?.focus()
      nameInputRef.current?.select()
    }
  }, [isEditingName])

  const initialData = useMemo(() => (automation ? automationToFormData(automation) : undefined), [automation])

  const handleSubmit = useCallback(
    async (data: AutomationFormData) => {
      try {
        setCappedOnEnable(false)
        await updateAutomation({...data, name: name.trim()})
        navigate(backHref)
      } catch (err) {
        if (isActiveLimitReachedError(err)) {
          setCappedOnEnable(true)
        }
        // Re-throw so AutomationForm re-enables the submit button for a retry.
        throw err
      }
    },
    [updateAutomation, navigate, backHref, name],
  )

  const handleNameBlur = useCallback(() => {
    setIsEditingName(false)
    requestAnimationFrame(() => titleButtonRef.current?.focus())
    if (name.trim() === '') {
      setName(automation?.name ?? '')
    }
  }, [name, automation])

  const handleNameKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
      if (e.key === 'Enter') {
        e.preventDefault()
        handleNameBlur()
        // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
      } else if (e.key === 'Escape') {
        setName(automation?.name ?? '')
        setIsEditingName(false)
      }
    },
    [handleNameBlur, automation],
  )
  const titleButtonRef = useRef<HTMLButtonElement>(null)
  const automationsListHref = `/${repository.ownerLogin}/${repository.name}/agents/automations`

  if (!automation) return null

  return (
    <div className={styles.container} data-hpc>
      <div className={styles.content}>
        <div className={editStyles.headerRow}>
          {isEditingName ? (
            <TextInput
              ref={nameInputRef}
              value={name}
              onChange={e => setName(e.target.value)}
              onBlur={handleNameBlur}
              onKeyDown={handleNameKeyDown}
              className={editStyles.nameInput}
              aria-label="Automation name"
              block
            />
          ) : (
            <button
              type="button"
              className={editStyles.editableTitle}
              onClick={() => setIsEditingName(true)}
              aria-label="Edit automation name"
              ref={titleButtonRef}
            >
              <Heading as="h2" className={editStyles.titleText}>
                {name}
              </Heading>
              <PencilIcon className={editStyles.pencilIcon} />
            </button>
          )}
          <ActionMenu>
            <ActionMenu.Anchor>
              <IconButton icon={KebabHorizontalIcon} aria-label="More options" variant="invisible" />
            </ActionMenu.Anchor>
            <ActionMenu.Overlay width="auto">
              <ActionList>
                <ActionList.Item onSelect={() => setIsEditingName(true)}>
                  <ActionList.LeadingVisual>
                    <PencilIcon />
                  </ActionList.LeadingVisual>
                  Edit title
                </ActionList.Item>
                <ActionList.Item variant="danger" onSelect={() => setIsDeleteDialogOpen(true)}>
                  <ActionList.LeadingVisual>
                    <TrashIcon />
                  </ActionList.LeadingVisual>
                  Delete automation
                </ActionList.Item>
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </div>
        {isDeleteDialogOpen && automationID && (
          <DeleteAutomationDialog
            automationId={automationID}
            onDeleted={() => navigate(automationsListHref)}
            onClose={() => setIsDeleteDialogOpen(false)}
          />
        )}
        {cappedOnEnable && <ActiveLimitReachedBanner />}
        <AutomationForm
          onCancel={() => navigate(backHref)}
          onSubmit={handleSubmit}
          submitLabel="Save"
          initialData={initialData}
          hideNameField
          initialTriggers={payload.triggers}
          initialToolGroups={payload.tools}
          orgAllowReadAccessTriggers={payload.orgAllowReadAccessTriggers}
          repoAllowReadAccessTriggers={payload.repoAllowReadAccessTriggers}
          submitDisabledNotice={repository.isEmpty ? EMPTY_REPO_NOTICE : undefined}
        />
      </div>
    </div>
  )
}
