import {useId, type ReactNode} from 'react'
import {Layout} from '@github-ui/pacer/Layout'
import {CurrentRepositoryProvider} from '@github-ui/current-repository'
import {useCurrentQueryRoute} from '@github-ui/react-core/future/use-current-query-route'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {RepoAgentsSidebar} from '../components/repo-agents-page/RepoAgentsSidebar'
import {ConsecutiveCAPI401sProvider} from '@github-ui/agent-sessions/contexts/ConsecutiveCAPI401sContext'
import {SidebarAgentFilterProvider} from '@github-ui/agent-sessions/contexts/SidebarAgentFilterContext'
import {useInitializeAuthToken} from '@github-ui/agent-sessions/hooks/use-initialize-auth-token'
import {useUpdateAppOffset} from '../hooks/use-update-app-offset'
import {useHideFooter} from '@github-ui/use-hide-footer'
import type {BaseRepoAgentsPayload} from '../types/repo-agents-payload'

/**
 * Shared layout for all repo-agents pages.
 * Provides the sidebar, repository context, and auth token initialization.
 */
export function RepoAgentsLayout({children}: {children: (payload: BaseRepoAgentsPayload) => ReactNode}) {
  useUpdateAppOffset()
  const currentRoute = useCurrentQueryRoute()
  const sidebarLabelId = useId()
  const {data: payload} = useRouteQuery(currentRoute, 'mainQuery')
  useHideFooter(true)

  useInitializeAuthToken(payload.initialAuthToken)

  return (
    <CurrentRepositoryProvider repository={payload.repository}>
      <ConsecutiveCAPI401sProvider>
        <SidebarAgentFilterProvider automationsVisible={payload.automationsVisible === true}>
          <Layout sidebarCondensable={false}>
            <Layout.Sidebar header={null} aria-labelledby={sidebarLabelId}>
              <span id={sidebarLabelId} className="sr-only">
                Agent navigation
              </span>
              <RepoAgentsSidebar
                currentUserLogin={payload.currentUser?.login}
                copilotMemoryEnabled={payload.copilotMemoryEnabled}
                copilotSetupStepsFilePath={payload.copilotSetupStepsFilePath}
                copilotCodingAgentEnabled={payload.copilotCodingAgentEnabled}
                userHasCCAByPolicy={payload.userHasCCAByPolicy}
                hasAgentsMd={payload.hasAgentsMd}
                automationsVisible={payload.automationsVisible}
              />
            </Layout.Sidebar>
            <Layout.ColumnLeft>{children(payload)}</Layout.ColumnLeft>
          </Layout>
        </SidebarAgentFilterProvider>
      </ConsecutiveCAPI401sProvider>
    </CurrentRepositoryProvider>
  )
}
