import {ActionList, ActionMenu, CounterLabel, IconButton, Link} from '@primer/react'
import {
  ChevronRightIcon,
  CopilotIcon,
  GitPullRequestIcon,
  IssueOpenedIcon,
  PlayIcon,
  PlusIcon,
  RepoIcon,
  ShieldCheckIcon,
  TagIcon,
  TerminalIcon,
  ToolsIcon,
  TrashIcon,
} from '@primer/octicons-react'
import type {Icon} from '@primer/octicons-react'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {announce} from '@github-ui/aria-live'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {PickerCard, PickerSection} from './PickerSection'
import type {SuggestionContext} from './suggest-tools-helpers'
import styles from './ToolsInput.module.css'
import {
  isSelectableToolGroup,
  type SelectableToolGroupId,
  type ToolDefinition,
  type ToolGroup,
} from './tool-definitions'
import {useSuggestTools, type SuggestToolsResult} from './use-suggest-tools'

/** Maps every selectable tool group to its icon; typed so the picker and catalog stay in sync. */
const TOOL_GROUP_ICON_MAP: Record<SelectableToolGroupId, Icon> = {
  issues: IssueOpenedIcon,
  'pull-requests': GitPullRequestIcon,
  coding: TerminalIcon,
  general: ToolsIcon,
  repos: RepoIcon,
  actions: PlayIcon,
  'code-security': ShieldCheckIcon,
  labels: TagIcon,
}

function getToolGroupIcon(groupId: string): Icon | undefined {
  return isSelectableToolGroup(groupId) ? TOOL_GROUP_ICON_MAP[groupId] : undefined
}

export interface ToolsInputProps {
  value: string[]
  onChange: (tools: string[]) => void
  toolGroups: ToolGroup[]
  loading?: boolean
  /** Form context for the "Suggest tools" button. When omitted the button is hidden. */
  suggestionContext?: SuggestionContext
}

export function ToolsInput({value: selectedTools, onChange, toolGroups, loading, suggestionContext}: ToolsInputProps) {
  const selectedToolNames = useMemo(() => new Set(selectedTools), [selectedTools])

  const activeGroups = useMemo(() => {
    const result: Array<{group: ToolGroup; entries: string[]}> = []
    for (const group of toolGroups) {
      const entries = group.tools.filter(t => selectedToolNames.has(t.id)).map(t => t.id)
      if (entries.length > 0) {
        result.push({group, entries})
      }
    }
    return result
  }, [selectedToolNames, toolGroups])

  const configuredToolGroups = useMemo(() => {
    return toolGroups.filter(toolGroup => isSelectableToolGroup(toolGroup.id))
  }, [toolGroups])

  const groupsWithAvailableTools = useMemo(
    () =>
      configuredToolGroups
        .map(g => ({
          group: g,
          unselected: g.tools.filter(t => !selectedToolNames.has(t.id)),
        }))
        .filter(({unselected}) => unselected.length > 0),
    [selectedToolNames, configuredToolGroups],
  )

  const addTools = useCallback(
    (toolIds: string[]) => {
      const newTools = toolIds.filter(id => !selectedToolNames.has(id))
      if (newTools.length > 0) {
        onChange([...selectedTools, ...newTools])
      }
    },
    [selectedTools, selectedToolNames, onChange],
  )

  const addSingleTool = useCallback(
    (toolId: string) => {
      if (!selectedToolNames.has(toolId)) {
        onChange([...selectedTools, toolId])
      }
    },
    [selectedTools, selectedToolNames, onChange],
  )

  const removeToolGroup = useCallback(
    (groupId: string) => {
      const group = toolGroups.find(g => g.id === groupId)
      if (!group) return
      const groupToolIds = new Set(group.tools.map(t => t.id))
      onChange(selectedTools.filter(id => !groupToolIds.has(id)))
    },
    [selectedTools, onChange, toolGroups],
  )

  const removeTool = useCallback(
    (toolId: string) => {
      onChange(selectedTools.filter(id => id !== toolId))
    },
    [selectedTools, onChange],
  )

  const mergeSuggestedTools = useCallback(
    // The hook only invokes onApply with non-empty, catalog-validated, dedup'd IDs.
    (newToolIds: string[]) => onChange(Array.from(new Set([...selectedTools, ...newToolIds]))),
    [selectedTools, onChange],
  )

  const hasAvailableTools = groupsWithAvailableTools.length > 0

  const suggestEnabled = suggestionContext !== undefined && isFeatureEnabled('copilot_automation_suggest_tools_enabled')

  const {suggest, isPending, lastResult} = useSuggestTools({
    toolGroups,
    selectedTools,
    onApply: mergeSuggestedTools,
  })

  const [menuOpen, setMenuOpen] = useState(false)
  const [dismissedResult, setDismissedResult] = useState(lastResult)

  const hasSelectableTools = toolGroups.some(g => isSelectableToolGroup(g.id) && g.tools.length > 0)
  const suggestInactiveReason = loading
    ? 'Loading available tools…'
    : !hasSelectableTools
      ? 'No tools available to suggest'
      : !suggestionContext?.prompt.trim()
        ? 'Add a prompt to enable suggestions'
        : ''
  const suggestInactive = suggestInactiveReason !== ''

  const handleSuggest = useCallback(
    (e?: React.MouseEvent<HTMLElement> | React.KeyboardEvent<HTMLElement>) => {
      e?.preventDefault()
      if (suggestInactive || isPending || !suggestionContext) return
      suggest({
        name: suggestionContext.name,
        description: suggestionContext.description,
        prompt: suggestionContext.prompt,
      })
    },
    [suggestInactive, isPending, suggestionContext, suggest],
  )

  const statusMessage = describeStatusResult(lastResult)
  const showStatusInMenu = statusMessage !== '' && !isPending && lastResult !== dismissedResult

  // Announce status messages to screen readers via a persistent live region
  const announcedResultRef = useRef<SuggestToolsResult>(lastResult)
  useEffect(() => {
    if (lastResult !== announcedResultRef.current) {
      const message = announceStatusResult(lastResult)
      if (message !== '') {
        announce(message)
      }
      announcedResultRef.current = lastResult
    }
  }, [lastResult])

  // Close menu automatically when tools are successfully added
  if (lastResult.kind === 'success' && lastResult !== dismissedResult && menuOpen && !isPending) {
    setMenuOpen(false)
    setDismissedResult(lastResult)
  }

  // Keep menu open while pending
  const handleOpenChange = useCallback(
    (open: boolean) => {
      if (!open && isPending) return
      if (!open) setDismissedResult(lastResult)
      setMenuOpen(open)
    },
    [isPending, lastResult],
  )

  const toolMenu = (
    <ActionMenu open={menuOpen} onOpenChange={handleOpenChange}>
      <ActionMenu.Button size="small" leadingVisual={PlusIcon} disabled={loading || !hasAvailableTools}>
        Choose a tool
      </ActionMenu.Button>
      <ActionMenu.Overlay width="medium">
        <ActionList>
          {suggestEnabled && (
            <>
              <ActionList.Item
                onSelect={handleSuggest}
                inactiveText={suggestInactiveReason || undefined}
                loading={isPending}
              >
                <ActionList.LeadingVisual>
                  <CopilotIcon />
                </ActionList.LeadingVisual>
                Suggest tools
                {showStatusInMenu && (
                  <ActionList.Description variant="block">
                    <span className={lastResult.kind === 'error' ? styles.statusError : undefined}>
                      {statusMessage}
                    </span>
                  </ActionList.Description>
                )}
              </ActionList.Item>
              <ActionList.Divider />
            </>
          )}
          {groupsWithAvailableTools.map(({group, unselected}) => {
            const GroupIcon = getToolGroupIcon(group.id)
            return (
              <ActionMenu key={group.id}>
                <ActionMenu.Anchor>
                  <ActionList.Item>
                    {GroupIcon != null && (
                      <ActionList.LeadingVisual>
                        <GroupIcon />
                      </ActionList.LeadingVisual>
                    )}
                    {group.name}
                    <ActionList.TrailingVisual>
                      <ChevronRightIcon />
                    </ActionList.TrailingVisual>
                  </ActionList.Item>
                </ActionMenu.Anchor>
                <ActionMenu.Overlay>
                  <ActionList>
                    <ActionList.Item onSelect={() => addTools(unselected.map(t => t.id))}>
                      All tools
                      <ActionList.TrailingVisual>
                        <CounterLabel aria-label={`${unselected.length} tools`}>{unselected.length}</CounterLabel>
                      </ActionList.TrailingVisual>
                    </ActionList.Item>
                    <ActionList.Divider />
                    <ToolScopeSection
                      heading="Read-only"
                      allLabel="All read-only tools"
                      tools={unselected.filter(t => t.scope === 'read')}
                      onAddAll={addTools}
                      onAddOne={addSingleTool}
                    />
                    <ToolScopeSection
                      heading="Read-write"
                      allLabel="All read-write tools"
                      tools={unselected.filter(t => t.scope === 'write')}
                      onAddAll={addTools}
                      onAddOne={addSingleTool}
                    />
                  </ActionList>
                </ActionMenu.Overlay>
              </ActionMenu>
            )
          })}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )

  return (
    <PickerSection
      label="Tools"
      caption={
        <>
          Select which tools the agent can use. Some built-in tools are always available. For more information, see{' '}
          <Link
            inline
            href="https://gh.io/cca-automations-docs"
            target="_blank"
            rel="noopener noreferrer"
            className="Link--inTextBlock"
          >
            the documentation
          </Link>
          .
        </>
      }
      menu={toolMenu}
      hasItems={activeGroups.length > 0}
    >
      {activeGroups.map(({group}) => {
        const GroupIcon = getToolGroupIcon(group.id)
        return (
          <PickerCard
            key={group.id}
            icon={GroupIcon != null ? <GroupIcon size={16} /> : undefined}
            title={group.name}
            removeLabel={`Remove all ${group.name} tools`}
            onRemove={() => removeToolGroup(group.id)}
          >
            <ToolList tools={group.tools} selectedNames={selectedToolNames} onRemove={removeTool} />
          </PickerCard>
        )
      })}
    </PickerSection>
  )
}

function describeStatusResult(result: SuggestToolsResult): string {
  switch (result.kind) {
    case 'empty':
      return 'No new tools suggested'
    case 'error':
      return result.errorMessage ?? "Couldn't suggest tools. Please try again."
    case 'success':
    case 'idle':
    default:
      return ''
  }
}

function announceStatusResult(result: SuggestToolsResult): string {
  if (result.kind === 'success') {
    const count = result.addedCount ?? 0
    return count === 1 ? 'Added 1 tool' : `Added ${count} tools`
  }
  return describeStatusResult(result)
}

/**
 * Renders one scope section (Read-only / Read-write) inside a tool group's
 * submenu, with an "All …" shortcut followed by the individual tools. Renders
 * nothing when the section has no unselected tools.
 */
function ToolScopeSection({
  heading,
  allLabel,
  tools,
  onAddAll,
  onAddOne,
}: {
  heading: string
  allLabel: string
  tools: ToolDefinition[]
  onAddAll: (toolIds: string[]) => void
  onAddOne: (toolId: string) => void
}) {
  if (tools.length === 0) return null

  return (
    <ActionList.Group>
      <ActionList.GroupHeading>{heading}</ActionList.GroupHeading>
      {tools.length > 1 && (
        <ActionList.Item onSelect={() => onAddAll(tools.map(t => t.id))}>
          {allLabel}
          <ActionList.TrailingVisual>
            <CounterLabel aria-label={`${tools.length} tools`}>{tools.length}</CounterLabel>
          </ActionList.TrailingVisual>
        </ActionList.Item>
      )}
      {tools.map(tool => (
        <ActionList.Item key={tool.id} onSelect={() => onAddOne(tool.id)}>
          {tool.name}
        </ActionList.Item>
      ))}
    </ActionList.Group>
  )
}

/** Renders the list of individual tools within a group card. */
function ToolList({
  tools,
  selectedNames,
  onRemove,
}: {
  tools: ToolDefinition[]
  selectedNames: Set<string>
  onRemove: (id: string) => void
}) {
  const selected = tools.filter(t => selectedNames.has(t.id))
  if (selected.length === 0) return null

  return (
    // eslint-disable-next-line jsx-a11y/no-redundant-roles -- list-style:none strips semantics in Safari/VoiceOver
    <ul className={styles.toolList} role="list">
      {selected.map(tool => (
        <li key={tool.id} className={styles.toolItem}>
          <span className={styles.toolName}>{tool.name}</span>
          <IconButton
            icon={TrashIcon}
            variant="invisible"
            size="small"
            onClick={() => onRemove(tool.id)}
            aria-label={`Remove ${tool.name}`}
          />
        </li>
      ))}
    </ul>
  )
}
