import {useQuery} from '@github-ui/react-query'
import {ownerAvatarPath} from '@github-ui/paths'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {collaboratorSearchUrl} from '../utils/api-url-helpers'

interface CollaboratorSearchResult {
  id: number | null
  login: string
  avatarUrl: string
}

/**
 * Searches repo collaborators via the item-pickers assignees endpoint.
 * Returns matching users for a given search query, used to populate
 * the author filter dropdown with typeahead results.
 *
 * Callers are expected to debounce the query before passing it in
 * (see CreatorSelectPanel for an example).
 */
export function useCollaboratorSearch(owner: string, repo: string, query: string) {
  // eslint-disable-next-line @github-ui/github-monorepo/require-query-persister -- Typeahead results are ephemeral and change with each keystroke; caching stale suggestions would degrade UX.
  return useQuery<CollaboratorSearchResult[]>({
    queryKey: ['collaborator-search', owner, repo, query],
    queryFn: async () => {
      const response = await verifiedFetchJSON(collaboratorSearchUrl({owner, repo, query}))
      if (!response.ok) return []

      const json = await response.json()
      if (!json?.data?.repository?.suggestedActors?.nodes) return []

      return json.data.repository.suggestedActors.nodes
        .filter((node: {login?: string}) => node.login)
        .map((node: {login: string; databaseId?: number; avatarUrl?: string}) => ({
          id: node.databaseId ?? null,
          login: node.login,
          avatarUrl: node.avatarUrl ?? ownerAvatarPath({owner: node.login}),
        }))
    },
    enabled: query.length >= 1 && !!owner && !!repo,
    staleTime: Infinity,
  })
}
