function useAgentFiltering(nwo: string, currentUserLogin?: string) {
  const [searchParams, setSearchParams] = useSearchParams()
  const enabled = isFeatureEnabled('copilot_mission_control_agent_filtering')
  const {data: rawAgents = [], isLoading: isLoadingAgents} = useTopLevelAgents(nwo)

  // HACK: The agents API doesn't return CLI/VSCode/JetBrains agents when the user's
  // cli_remote_control policy isn't enabled, but we still need their IDs for
  // agent_group filtering to work. Inject them unconditionally so that
  // selecting "CLI", "VS Code", or "JetBrains" in the type filter resolves to the correct
  // include_agent_ids values sent to CMC.
  const agents = useMemo(() => {
    let result = rawAgents
    if (!result.some(a => a.group === 'cli')) {
      result = [
        ...result,
        {
          id: '1693627',
          slug: 'copilot-developer-cli',
          display_name: 'Copilot CLI',
          avatar_url: '',
          doc_url: '',
          group: 'cli' as const,
        },
      ]
    }
    if (!result.some(a => a.group === 'vscode')) {
      result = [
        ...result,
        {
          id: '797352',
          slug: 'vscode-chat',
          display_name: 'Copilot in VS Code',
          avatar_url: '',
          doc_url: '',
          group: 'vscode' as const,
        },
      ]
    }
    if (!result.some(a => a.group === 'jetbrains')) {
      result = [
        ...result,
        {
          id: '3135702',
          slug: 'jetbrains-chat',
          display_name: 'Copilot in JetBrains',
          avatar_url: '',
          doc_url: '',
          group: 'jetbrains' as const,
        },
      ]
    }
    return result
  }, [rawAgents])

  // Read selected groups from the parsed ?q= param. In q-syntax mode,
  // writeFiltersToSearchParams removes agent_group from the URL and encodes
  // types inside ?q=, so we parse the URL to pick up the selection.
  const parsedFilters = useMemo(
    () => readFiltersFromSearchParams(searchParams, currentUserLogin),
    [searchParams, currentUserLogin],
  )
  const selectedGroups = useMemo(() => {
    if (!enabled) return []
    return parsedFilters.types
  }, [enabled, parsedFilters.types])

  const agentIds = useMemo(() => {
    if (!enabled || selectedGroups.length === 0) return undefined
    return agents.flatMap(a => (selectedGroups.includes(a.group ?? 'cloud') && a.id != null ? [Number(a.id)] : []))
  }, [selectedGroups, agents, enabled])

  const handleAgentFilterChange = useCallback(
    (groups: string[]) => {
      setSearchParams(prev => {
        const next = new URLSearchParams(prev)
        if (groups.length > 0) {
          next.set('agent_group', groups.join(','))
        } else {
          next.delete('agent_group')
        }
        next.delete('page')
        return next
      })
    },
    [setSearchParams],
  )

  if (!enabled) {
    // Always return agents/isLoadingAgents — the session filter bar
    // (copilot_mission_control_session_filters) uses them for agent dropdown options
    // even when group-based agent filtering is off.
    return {
      agents,
      isLoadingAgents,
      selectedGroups: undefined,
      agentIds: undefined,
      handleAgentFilterChange: undefined,
    }
  }

  return {agents, isLoadingAgents, selectedGroups, agentIds, handleAgentFilterChange}
}

export function RepoAgentsView() {
  const {data: payload} = useRouteQuery(repoAgentsRoute, 'mainQuery')
  const {
    repository,
    tasks: initialTasks,
    pullRequestMap: initialPullRequestMap,
    currentUser,
    canCreateTasks,
    hasPaidCopilotAccess,
    hasCEorCBAccess,
    icebreakerVariant,
    agentQuotaSnapshot,
    userHasCCAByPolicy,
    userHasCodeReviewAccess,
    copilotCodingAgentEnabledForRepo,
  } = payload

  const accessState = getAgentAccessState({
    copilotCodingAgentEnabledForRepo,
    userHasCCAByPolicy,
    hasCEorCBAccess,
    hasPaidCopilotAccess,
    userHasCodeReviewAccess,
  })
  const {data: chatPayload} = useRouteQuery(repoAgentsRoute, 'copilotChatPayload')
  const [failedTaskCreationAttempts, setFailedTaskCreationAttempts] = useState<FailedAPITaskCreationAttempt[]>([])
  const [searchParams, setSearchParams] = useSearchParams()

  const nwo = `${repository.ownerLogin}/${repository.name}`
  const {agents, isLoadingAgents, selectedGroups, agentIds, handleAgentFilterChange} = useAgentFiltering(
    nwo,
    currentUser?.login,
  )
  const {data: customAgents} = useSubAgents({
    repo: {owner: repository.ownerLogin, nameOnly: repository.name},
  })

  // Derive active tab and filter values from the unified ?q= param
  const filtersEnabled = isFeatureEnabled('copilot_mission_control_session_filters')
  const parsedFilters = useMemo(
    () => readFiltersFromSearchParams(searchParams, currentUser?.login),
    [searchParams, currentUser?.login],
  )
  const activeTab: ActiveTab = parsedFilters.status
  const setActiveTab = useCallback(
    (tab: ActiveTab) => {
      setSearchParams(prev => {
        const next = new URLSearchParams(prev)
        if (filtersEnabled) {
          // Update the q= param with the new tab (is:open / is:closed / all).
          // Always set q (even to an empty string) so the reader stays in q-syntax
          // mode; deleting it would fall back to the legacy default of 'open' and
          // make the "All" tab revert to "Open" when no other qualifiers remain.
          const currentQ = next.get('q') ?? ''
          next.set('q', setStatusInQuery(currentQ, tab))
        } else {
          // Legacy mode: use completed param
          if (tab === 'closed') next.set('completed', 'true')
          else if (tab === 'all') next.set('completed', 'all')
          else next.delete('completed')
        }
        next.delete('page')
        return next
      })
    },
    [setSearchParams, filtersEnabled],
  )

  // Read filter values from the parsed ?q= param for server-side filtering
  // author is always read because the sidebar sets it on initial load
  const authorParams = parsedFilters.creators
  const excludeAuthorFilter = filtersEnabled
    ? parsedFilters.excludedCreators.length > 0
      ? parsedFilters.excludedCreators.join(',')
      : null
    : null
  const statusFilter = filtersEnabled
    ? parsedFilters.detailedStatuses.length > 0
      ? parsedFilters.detailedStatuses.join(',')
      : null
    : null
  const agentFilter = useMemo(
    () => (filtersEnabled ? parsedFilters.agents : []),
    [filtersEnabled, parsedFilters.agents],
  )
  const sortFilter = filtersEnabled ? (parsedFilters.sort !== 'newest' ? parsedFilters.sort : null) : null
  const queryFilter = filtersEnabled ? parsedFilters.freeText || null : null

  // Detect "Needs Attention" mode (status:needs_attention). Tabs don't make sense
  // here since it only shows open/unarchived sessions, so we hide them. Uses the
  // unified parser so it works for both legacy (state=waiting_for_user) and ?q= URLs.
  const isShowingNeedsAttention = parsedFilters.detailedStatuses.includes('needs_attention')

  // "Created by me" mode: exactly 1 author matching current user, with no exclude_author filter.
  const isFilteredByCurrentUser = currentUser?.login
    ? authorParams.length === 1 && authorParams.includes(currentUser.login) && !excludeAuthorFilter
    : false

  const {resolvedAgentIds, resolvedCustomAgentNames, agentFilterReady} = useResolvedAgentFilter(
    agentFilter,
    agents,
    isLoadingAgents,
    agentIds,
  )

  // Get type filter from query params (e.g., 'review' for CCR tasks)
  const showCodeReviewsTab = isFeatureEnabled('copilot_mission_control_code_review_tab')
  const taskType = showCodeReviewsTab ? (searchParams.get('type') ?? undefined) : undefined
  const isCodeReviewMode = taskType === 'review'

  const {resolvedCreatorIds, authorFilterReady} = useResolvedCreatorIds({
    authorParams,
    isFilteredByCurrentUser,
    isCodeReviewMode,
    currentUser,
    repository,
  })
  const effectiveCreatorIds = resolvedCreatorIds

  const {
    tasks: rawTasks,
    isError,
    isLoading,
    isFetching,
    hasNextPage,
    counts,
    isPRLoading,
    dataUpdatedAt,
  } = useRepoTasks({
    owner: repository.ownerLogin,
    repo: repository.name,
    repoId: repository.id,
    creatorIds: effectiveCreatorIds,
    initialData: initialTasks,
    initialPullRequestsMap: initialPullRequestMap,
    fetchArchivedTasks: activeTab === 'closed' ? true : activeTab === 'open' ? false : undefined,
    tab: undefined,
    taskType,
    agentIds: resolvedAgentIds,
    customAgentName: resolvedCustomAgentNames?.join(','),
    statuses: statusFilter ? statusFilter.split(',').filter(Boolean) : undefined,
    sort: sortFilter ?? undefined,
    query: queryFilter ?? undefined,
    enabled: agentFilterReady && authorFilterReady,
  })

  const tasks = rawTasks

  const taskListMutationConfig = useMemo(
    () => ({
      queryKey: repoTasksQueryKey(
        repository.ownerLogin,
        repository.name,
        effectiveCreatorIds,
        1, // page - new tasks always insert at page 1
        false, // New tasks appear in the Open tab (archived=false)
        taskType,
        resolvedAgentIds,
        resolvedCustomAgentNames?.join(','),
        statusFilter ? statusFilter.split(',').filter(Boolean) : undefined,
        sortFilter ?? undefined,
        queryFilter ?? undefined,
        undefined, // agentSlugs - resolved via resolvedAgentIds
      ),
      getFlatTaskList,
      setFlatTaskList,
      pageSize: PAGE_SIZE,
    }),
    [
      repository.ownerLogin,
      repository.name,
      effectiveCreatorIds,
      taskType,
      resolvedAgentIds,
      resolvedCustomAgentNames,
      statusFilter,
      sortFilter,
      queryFilter,
    ],
  )

  const {createTask} = useCreateAPITask<FetchRepoTasksResponse>({
    ...taskListMutationConfig,
    onError: (error: Error, variables: CreateAPITaskMutationParams) => {
      setFailedTaskCreationAttempts(prev => [
        ...prev,
        {
          ...variables,
          errorMessage: error.message,
          timestamp: new Date().toISOString(),
        },
      ])
    },
  })
  const localDeviceMutation = useCreateLocalDeviceSession<FetchRepoTasksResponse>({
    optimisticTaskListConfig: taskListMutationConfig,
  })
  const onLocalDeviceSubmit = localDeviceMutation.mutateAsync

  const {
    chatInputRef,
    textAreaRef,
    visible: icebreakersVisible,
    handleSelect: handleIcebreakerSelect,
    handleDismiss: handleIcebreakerDismiss,
    handleIcebreakerSubmit,
  } = useIcebreakers({location: 'repo_agents', variant: icebreakerVariant})

  const handleUserSubmit = useCallback(
    async (
      content: string,
      selectedRepo: DropdownRepository | null,
      selectedBranch: string,
      selectedAgent: SelectedAgent,
      _selectedMode?: IntentDetectionMode,
      modelId?: string,
      createPullRequest?: boolean,
    ) => {
      handleIcebreakerSubmit(content)
      const trimmedContent = content.trim()
      if (trimmedContent === '') return
      if (!selectedRepo) return

      // Switch to open tab and reset pagination on new task creation
      setActiveTab('open')

      // Create the task
      createTask({
        nwo: selectedRepo.nameWithOwner,
        problemStatement: trimmedContent,
        customAgent: selectedAgent?.subAgentSlug,
        agentId: selectedAgent?.topLevelAgentId,
        model: modelId,
        baseRef: selectedBranch || undefined,
        createPullRequest,
        eventType: 'repo_agents',
        intentDetectionMode: 'task', // For now we explicitly don't use intent detection on this path
      })
    },
    [handleIcebreakerSubmit, createTask, setActiveTab],
  )

  const handleRetry = (attemptIndex: number) => {
    const attempt = failedTaskCreationAttempts[attemptIndex]
    if (attempt) {
      setFailedTaskCreationAttempts(prev => prev.filter((_, index) => index !== attemptIndex))
      createTask(getAPITaskParamsFromAttempt(attempt))
    }
  }

  useEffect(() => {
    let title = ''
    if (isCodeReviewMode) {
      title = 'Code reviews'
    } else {
      title = 'Agents'
    }
    title += ` · ${repository.nameWithOwner}`
    setTitle(title)
  }, [repository.nameWithOwner, isCodeReviewMode])

  return (
    <CurrentRepositoryProvider repository={repository}>
      <div className={styles.container} data-hpc>
        <div className={styles.content}>
          <header className={styles.header}>
            <Heading as="h2" className={styles.title}>
              {isCodeReviewMode ? 'Code reviews' : 'Sessions'}
            </Heading>
          </header>
          {!isCodeReviewMode && canCreateTasks && accessState.kind === 'full' && (
            <CopilotChatProviders chatPayload={chatPayload}>
              <IntentDetectionProvider>
                <div className={styles.taskForm}>
                  <NewTaskChatInput
                    handleUserSubmit={handleUserSubmit}
                    initialRepo={repository}
                    hideRepoSelector
                    isNewConversation
                    chatInputRef={chatInputRef}
                    textAreaRef={textAreaRef}
                    onLocalDeviceSubmit={onLocalDeviceSubmit}
                    agentQuotaSnapshot={agentQuotaSnapshot}
                  />
                </div>
                {icebreakersVisible && (
                  <AgentIcebreakers
                    onSelect={handleIcebreakerSelect}
                    onDismiss={handleIcebreakerDismiss}
                    location="repo_agents"
                    variant={icebreakerVariant}
                  />
                )}
              </IntentDetectionProvider>
            </CopilotChatProviders>
          )}
          <TaskCreationFailedBannerList
            attempts={failedTaskCreationAttempts}
            onRetry={handleRetry}
            onDismiss={index => setFailedTaskCreationAttempts(prev => prev.filter((_, i) => i !== index))}
          />
          {isCodeReviewMode ? (
            <CodeReviewTaskList
              tasks={tasks}
              isError={isError}
              isLoading={isLoading}
              isFetching={isFetching}
              isPRLoading={isPRLoading}
              hasNextPage={hasNextPage}
              openCount={counts?.open}
              closedCount={counts?.closed}
              dataUpdatedAt={dataUpdatedAt}
            />
          ) : (
            <TaskActionProviders>
              <ArchiveErrorBanner />
              <RepoTaskList
                tasks={tasks}
                isError={isError}
                isLoading={isLoading}
                isFetching={isFetching}
                isPRLoading={isPRLoading}
                activeTab={activeTab}
                hasNextPage={hasNextPage}
                openCount={counts?.open}
                closedCount={counts?.closed}
                currentUserId={currentUser?.id}
                currentUserLogin={currentUser?.login}
                accessState={accessState}
                dataUpdatedAt={dataUpdatedAt}
                filtersEnabled={filtersEnabled}
                hideTabs={isShowingNeedsAttention}
                isFilteredByCurrentUser={isFilteredByCurrentUser}
                excludeAuthorFilter={excludeAuthorFilter}
                agents={agents}
                isLoadingAgents={isLoadingAgents}
                selectedGroups={selectedGroups}
                onAgentFilterChange={handleAgentFilterChange}
                customAgents={customAgents}
              />
            </TaskActionProviders>
          )}
          <CopilotDisclosure />
        </div>
      </div>
    </CurrentRepositoryProvider>
  )
}
