/**
 * Derives a single access state from the raw payload booleans.
 *
 * "full"         – CCA enabled for repo AND user has policy → show task input, normal empty states
 * "ccr-only"     – user has Copilot Code Review but not CCA → can view CCR sessions only
 * "cli-only"     – user can use CLI --remote but not web task creation
 *   cta variants tell the empty state which call-to-action link to show:
 *     "contact-admin" – managed user, needs admin to enable
 *     "enable"        – paid user, can self-enable CCA
 *     "upgrade"       – free user, needs to upgrade plan
 */
export type AgentAccessState =
  | {kind: 'full'}
  | {kind: 'ccr-only'}
  | {kind: 'cli-only'; cta: 'contact-admin' | 'enable' | 'upgrade'}

export function getAgentAccessState({
  copilotCodingAgentEnabledForRepo,
  userHasCCAByPolicy,
  hasCEorCBAccess,
  hasPaidCopilotAccess,
  userHasCodeReviewAccess,
}: {
  copilotCodingAgentEnabledForRepo: boolean
  userHasCCAByPolicy: boolean
  hasCEorCBAccess: boolean
  hasPaidCopilotAccess: boolean
  userHasCodeReviewAccess?: boolean
}): AgentAccessState {
  if (copilotCodingAgentEnabledForRepo && userHasCCAByPolicy) {
    return {kind: 'full'}
  }

  if (userHasCodeReviewAccess && !userHasCCAByPolicy) {
    return {kind: 'ccr-only'}
  }

  if (hasCEorCBAccess) {
    return {kind: 'cli-only', cta: 'contact-admin'}
  }

  if (hasPaidCopilotAccess) {
    return {kind: 'cli-only', cta: 'enable'}
  }

  return {kind: 'cli-only', cta: 'upgrade'}
}
