import {ActionList, ActionMenu, Button, IconButton, Link, TextInput} from '@primer/react'
import {
  ClockIcon,
  GitPullRequestIcon,
  InfoIcon,
  IssueOpenedIcon,
  PlusIcon,
  XCircleFillIcon,
  XIcon,
} from '@primer/octicons-react'
import type {Icon} from '@primer/octicons-react'
import {MarkdownRenderer} from '@github-ui/copilot-markdown'
import {useCallback, useEffect, useId, useMemo, useRef, useState} from 'react'

import {isFeatureEnabled} from '@github-ui/feature-flags'
import type {JSFeatureFlag} from '@github-ui/feature-flags/client-feature-flags'
import {useRuntimeEnvironment} from '@github-ui/ssr-utils/use-runtime-environment'

import {PickerCard, PickerSection} from './PickerSection'
