import type {Trigger, TriggerField, SelectedTrigger} from './types'

/**
 * Renders a string with markdown-style [text](url) links as inline <Link> elements.
 * Only handles simple links — does not support escaped brackets/parentheses in link text or URLs.
 * This is intentional as descriptions come from our controlled trigger catalog.
 */
export function renderMarkdownLinks(text: string): React.ReactNode {
  const parts = text.split(/(\[[^[\]]+]\([^()]+\))|(`[^`]+`)/)
  return parts.map((part, i) => {
    if (!part) return null
    const linkMatch = part.match(/^\[([^[\]]+)]\(([^()]+)\)$/)
    if (linkMatch) {
      return (
        <Link
          // eslint-disable-next-line @eslint-react/no-array-index-key
          key={`link-${i}`}
          inline
          href={linkMatch[2]}
          target="_blank"
          rel="noopener noreferrer"
          className="Link--inTextBlock"
        >
          {linkMatch[1]}
        </Link>
      )
    }
    const codeMatch = part.match(/^`([^`]+)`$/)
    if (codeMatch) {
      // eslint-disable-next-line @eslint-react/no-array-index-key
      return <code key={`code-${i}`}>{codeMatch[1]}</code>
    }
    return part
  })
}

const TRIGGER_ICON_MAP: Record<string, Icon> = {
  issues: IssueOpenedIcon,
  workflow_run: XCircleFillIcon,
  interval: ClockIcon,
  pull_request_opened: GitPullRequestIcon,
  pull_request_synchronize: GitPullRequestIcon,
  pull_request_merged: GitPullRequestIcon,
}

const PULL_REQUEST_TRIGGER_FLAGS: Partial<Record<string, JSFeatureFlag>> = {
  pull_request_opened: 'copilot_swe_agent_pull_request_opened_trigger',
  pull_request_synchronize: 'copilot_swe_agent_pull_request_synchronize_trigger',
  pull_request_merged: 'copilot_swe_agent_pull_request_merged_trigger',
}

const TRIGGER_ICON_COLOR_MAP: Record<string, string> = {
  issues: 'var(--fgColor-open)',
  pull_request_opened: 'var(--fgColor-open)',
  pull_request_synchronize: 'var(--fgColor-attention)',
  pull_request_merged: 'var(--fgColor-done)',
}

const DAY_OF_WEEK_LABELS: Record<string, string> = {
  '0': 'Sunday',
  '1': 'Monday',
  '2': 'Tuesday',
  '3': 'Wednesday',
  '4': 'Thursday',
  '5': 'Friday',
  '6': 'Saturday',
}
// Order shown to users: week starts on Monday. Values stay as ISO-style ints
// where 0 = Sunday, so the backend's day-of-week semantics are unchanged.
const DAY_OF_WEEK_OPTIONS = ['1', '2', '3', '4', '5', '6', '0']

const HOUR_UTC_OPTIONS = Array.from({length: 24}, (_, i) => String(i))

const INTERVAL_TYPE_LABELS: Record<string, string> = {
  hourly: 'Hourly',
  daily: 'Daily',
  weekly: 'Weekly',
}

// Default anchor values used when a user picks a frequency that requires the
// anchor and the field hasn't been set yet. These are interpreted as *local*
// time (9 AM Monday in the user's timezone) and converted to a UTC anchor
// via localToUTCAnchor before being stored.
const DEFAULT_LOCAL_HOUR = '9'
const DEFAULT_LOCAL_DAY_OF_WEEK = '1'

// Anchor fields are hardcoded client-side rather than catalogue-driven because
// they're fixed enumerations whose display labels and conditional rendering
// don't benefit from a server roundtrip. AutomationForm imports this to drive
// serialization (single numeric value, omitted when empty).
export const INTERVAL_ANCHOR_FIELDS = ['day_of_week', 'hour_utc'] as const
export type IntervalAnchorField = (typeof INTERVAL_ANCHOR_FIELDS)[number]

function isAnchorFieldVisible(field: IntervalAnchorField, intervalType: string | undefined): boolean {
  if (intervalType === 'weekly') return true
  if (intervalType === 'daily') return field === 'hour_utc'
  return false
}

// Reference week anchored to the current week's Sunday so the DST state of
// the reference date matches today's runtime DST state. Pinning to a fixed
// date in January (or any other static date) would shift conversions by an
// hour for half the year in DST-observing regions.
//
// refDateUTC must use UTC arithmetic end-to-end and refDateLocal must use
// local arithmetic end-to-end. Mixing them — e.g. building a local-midnight
// Date and then reading getUTCDate() off it — silently shifts the result by
// ±1 day for any timezone where local Sunday 00:00 falls on a different UTC
// date than UTC Sunday 00:00 (i.e. every timezone east of UTC, plus London
// during BST).
function refDateUTC(utcDay: number, utcHour: number): Date {
  const now = new Date()
  // Roll back today's UTC date to this week's UTC Sunday, then add utcDay
  // days. Date.UTC handles negative or month-overflowing day-of-month
  // arguments correctly, so the subtraction is safe at month boundaries.
  const dayOfMonth = now.getUTCDate() - now.getUTCDay() + utcDay
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), dayOfMonth, utcHour, 0, 0))
}

function refDateLocal(localDay: number, localHour: number, localMinute: number = 0): Date {
  const now = new Date()
  // Symmetric to refDateUTC but in local time so the resulting Date carries
  // the user's chosen weekday at the requested local clock time. Subtracting
  // getDay() rolls back to this week's local Sunday.
  const dayOfMonth = now.getDate() - now.getDay() + localDay
  return new Date(now.getFullYear(), now.getMonth(), dayOfMonth, localHour, localMinute, 0)
}

/**
 * Convert a stored UTC anchor (day, hour) into the corresponding local day,
 * hour, and minute. Includes minute so half-hour-offset timezones (IST,
 * Newfoundland) round-trip cleanly — getUTCHours/getHours alone would drop
 * the :30. Pass `isBrowser=false` (SSR / initial client render) to get UTC
 * values unchanged so server and client agree on the first paint.
 */
export function utcToLocalAnchor(
  utcDay: number,
  utcHour: number,
  isBrowser: boolean,
): {localDay: number; localHour: number; localMinute: number} {
  if (!isBrowser) return {localDay: utcDay, localHour: utcHour, localMinute: 0}
  const d = refDateUTC(utcDay, utcHour)
  return {localDay: d.getDay(), localHour: d.getHours(), localMinute: d.getMinutes()}
}

/**
 * Convert a local-picker (day, hour, minute) selection back into the UTC
 * anchor we persist. Minute is optional and defaults to zero. Only called
 * from user event handlers so it always runs on the client; no SSR fallback
 * needed.
 */
export function localToUTCAnchor(
  localDay: number,
  localHour: number,
  localMinute: number = 0,
): {utcDay: number; utcHour: number} {
  const d = refDateLocal(localDay, localHour, localMinute)
  return {utcDay: d.getUTCDay(), utcHour: d.getUTCHours()}
}

/** Format a local time as `HH:MM`. */
function formatLocalTime(hour: number, minute: number): string {
  return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`
}

function renderTriggerIcon(triggerName: string) {
  const IconComponent = TRIGGER_ICON_MAP[triggerName]
  return IconComponent ? <IconComponent /> : null
}

/**
 * Initializes a SelectedTrigger with default field values based on the definition.
 * Fields with options get their first option pre-selected; others start empty.
 * For the interval trigger, seeds anchor defaults derived from the user's
 * local time (9 AM Monday local → corresponding UTC anchor). Only called from
 * client event handlers so direct local-Date arithmetic is safe.
 */
function initSelectedTrigger(definition: Trigger): SelectedTrigger {
  const fieldValues: Record<string, string[]> = {}
  for (const field of definition.fields) {
    if (field.options && field.options.length > 0) {
      const firstOption = field.options[0]
      fieldValues[field.name] = firstOption !== undefined ? [firstOption] : []
    } else {
      fieldValues[field.name] = []
    }
  }
  if (definition.name === 'interval') {
    // Seed only the anchors that are visible for the initial interval type,
    // so an hourly schedule (default) doesn't carry hidden anchor values
    // through to the submitted shape.
    const initialType = fieldValues.types?.[0]
    const {utcDay, utcHour} = localToUTCAnchor(Number(DEFAULT_LOCAL_DAY_OF_WEEK), Number(DEFAULT_LOCAL_HOUR))
    if (isAnchorFieldVisible('day_of_week', initialType)) {
      fieldValues.day_of_week = [String(utcDay)]
    }
    if (isAnchorFieldVisible('hour_utc', initialType)) {
      fieldValues.hour_utc = [String(utcHour)]
    }
  }
  return {name: definition.name, fieldValues}
}

export interface TriggerInputProps {
  value: SelectedTrigger[]
  onChange: (triggers: SelectedTrigger[]) => void
  triggers: Trigger[]
  loading?: boolean
  footer?: React.ReactNode
}

// Generate a unique row ID using a simple incrementing counter scoped to this module
let nextRowId = 0
function genRowId(): string {
  return `row-${nextRowId++}`
}

export function TriggerInput({value: selectedTriggers, onChange, triggers, loading, footer}: TriggerInputProps) {
  const labelId = useId()
  const [filterRows, setFilterRows] = useState<Record<string, Array<{id: string; value: string}>>>({})
  const addFilterButtonRef = useRef<Map<string, HTMLButtonElement>>(new Map())
  const {isBrowser} = useRuntimeEnvironment()
  const triggerMenuButtonRef = useRef<HTMLButtonElement>(null)
  const tagInputRef = useRef<Map<string, HTMLInputElement>>(new Map())
  // Keyed by trigger name so multiple query-bearing triggers keep independent focus.
  const queryInputRef = useRef<Map<string, HTMLInputElement>>(new Map())

  useEffect(() => {
    const tagRef = tagInputRef.current
    const queryRef = queryInputRef.current
    const addBtnRef = addFilterButtonRef.current
    return () => {
      tagRef.clear()
      queryRef.clear()
      addBtnRef.clear()
    }
  }, [])

  // Defensive fallback used by anchor dropdowns when fieldValues are
  // unexpectedly empty. Computed once and shared with the seeding paths so a
  // missing value displays the same time the user would otherwise see seeded.
  const defaultAnchorUTC = useMemo(
    () => localToUTCAnchor(Number(DEFAULT_LOCAL_DAY_OF_WEEK), Number(DEFAULT_LOCAL_HOUR)),
    [],
  )

  // Seed anchor defaults for pre-loaded interval triggers (e.g. from suggested
  // automations) that arrive with `types` set but missing `hour_utc`/`day_of_week`.
  // Without this, the displayed fallback values won't be serialized on submit.
  // Re-seeds whenever the interval type changes (e.g. daily → weekly adds day_of_week).
  const seededIntervalTypeRef = useRef<string | null>(null)
  useEffect(() => {
    const intervalTrigger = selectedTriggers.find(t => t.name === 'interval')
    if (!intervalTrigger) return
    const intervalType = intervalTrigger.fieldValues.types?.[0]
    if (!intervalType) return
    if (seededIntervalTypeRef.current === intervalType) return

    let needsUpdate = false
    const nextFieldValues = {...intervalTrigger.fieldValues}
    for (const anchor of INTERVAL_ANCHOR_FIELDS) {
      if (isAnchorFieldVisible(anchor, intervalType) && (nextFieldValues[anchor] ?? []).length === 0) {
        nextFieldValues[anchor] =
          anchor === 'hour_utc' ? [String(defaultAnchorUTC.utcHour)] : [String(defaultAnchorUTC.utcDay)]
        needsUpdate = true
      }
    }
    if (needsUpdate) {
      seededIntervalTypeRef.current = intervalType
      onChange(selectedTriggers.map(t => (t.name === 'interval' ? {...t, fieldValues: nextFieldValues} : t)))
    } else {
      // All anchors already present for this type — mark as seeded without triggering onChange
      seededIntervalTypeRef.current = intervalType
    }
  }, [selectedTriggers, onChange, defaultAnchorUTC])

  const selectedNames = useMemo(() => new Set(selectedTriggers.map(t => t.name)), [selectedTriggers])
  const availableTriggers = useMemo(
    () =>
      triggers.filter(trigger => {
        if (selectedNames.has(trigger.name)) return false
        if (!Object.prototype.hasOwnProperty.call(TRIGGER_ICON_MAP, trigger.name)) return false
        const flag = PULL_REQUEST_TRIGGER_FLAGS[trigger.name]
        if (flag && !isFeatureEnabled(flag)) return false
        return true
      }),
    [triggers, selectedNames],
  )

  const addTrigger = useCallback(
    (definition: Trigger) => {
      if (!selectedNames.has(definition.name)) {
        onChange([...selectedTriggers, initSelectedTrigger(definition)])
      }
    },
    [selectedTriggers, selectedNames, onChange],
  )

  const removeTrigger = useCallback(
    (name: string) => {
      onChange(selectedTriggers.filter(t => t.name !== name))
      setFilterRows(prev => {
        const next = {...prev}
        for (const key of Object.keys(next)) {
          if (key.startsWith(`${name}:`)) delete next[key]
        }
        return next
      })
      requestAnimationFrame(() => triggerMenuButtonRef.current?.focus())
    },
    [selectedTriggers, onChange],
  )

  const updateFieldValue = useCallback(
    (triggerName: string, fieldName: string, values: string[]) => {
      onChange(
        selectedTriggers.map(t => {
          if (t.name !== triggerName) return t
          const nextFieldValues = {...t.fieldValues, [fieldName]: values}
          // When the interval `types` changes, clear anchors that no longer
          // apply (so they don't get silently submitted) and seed local-time
          // defaults for anchors that now do apply (so the user lands on a
          // valid state without an extra picker interaction).
          if (triggerName === 'interval' && fieldName === 'types') {
            const newType = values[0]
            const seed = localToUTCAnchor(Number(DEFAULT_LOCAL_DAY_OF_WEEK), Number(DEFAULT_LOCAL_HOUR))
            for (const anchor of INTERVAL_ANCHOR_FIELDS) {
              if (!isAnchorFieldVisible(anchor, newType)) {
                nextFieldValues[anchor] = []
              } else if ((nextFieldValues[anchor] ?? []).length === 0) {
                nextFieldValues[anchor] = anchor === 'hour_utc' ? [String(seed.utcHour)] : [String(seed.utcDay)]
              }
            }
          }
          return {...t, fieldValues: nextFieldValues}
        }),
      )
    },
    [selectedTriggers, onChange],
  )

  const triggerMenu = (
    <ActionMenu>
      <ActionMenu.Button
        ref={triggerMenuButtonRef}
        size="small"
        leadingVisual={PlusIcon}
        disabled={loading || availableTriggers.length === 0}
      >
        Choose a trigger
      </ActionMenu.Button>
      <ActionMenu.Overlay width="medium">
        <ActionList>
          {availableTriggers.map(definition => (
            <ActionList.Item key={definition.name} onSelect={() => addTrigger(definition)}>
              <ActionList.LeadingVisual>{renderTriggerIcon(definition.name)}</ActionList.LeadingVisual>
              <span>{definition.title}</span>
            </ActionList.Item>
          ))}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )

  const renderOptionsDropdown = (trigger: SelectedTrigger, field: TriggerField) => {
    const currentValues = trigger.fieldValues[field.name] ?? []
    const visibleOptions = field.options ?? []
    const labelFor = (value: string) =>
      trigger.name === 'interval' && field.name === 'types' ? (INTERVAL_TYPE_LABELS[value] ?? value) : value
    const triggerDef = triggers.find(t => t.name === trigger.name)
    const triggerTitle = triggerDef?.title ?? trigger.name
    const displayValue = labelFor(currentValues[0] ?? visibleOptions[0] ?? '')
    return (
      <ActionMenu key={field.name}>
        <ActionMenu.Button
          size="small"
          className={styles.filterButton}
          aria-label={`${triggerTitle} ${field.name}: ${displayValue}`}
        >
          {displayValue}
        </ActionMenu.Button>
        <ActionMenu.Overlay>
          <ActionList selectionVariant="single">
            {visibleOptions.map(opt => (
              <ActionList.Item
                key={opt}
                selected={currentValues.includes(opt)}
                onSelect={() => updateFieldValue(trigger.name, field.name, [opt])}
              >
                {labelFor(opt)}
              </ActionList.Item>
            ))}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    )
  }

  /**
   * Renders the hour-of-day picker for the interval trigger. Stored value is
   * a UTC hour (0–23); the picker displays the user's *local* hour and minute
   * (so half-hour-offset timezones like IST round-trip cleanly) and converts
   * back to UTC on selection. For weekly schedules the UTC day_of_week stored
   * value also shifts when the hour change crosses a UTC day boundary, so both
   * fields are written together; for daily schedules day_of_week is left
   * unchanged because it isn't part of the schedule. During SSR / initial
   * hydration we render UTC values directly (isBrowser=false) so server output
   * matches the first client render.
   */
  const renderHourDropdown = (trigger: SelectedTrigger) => {
    const intervalType = trigger.fieldValues.types?.[0]
    const utcHour = Number(trigger.fieldValues.hour_utc?.[0] ?? defaultAnchorUTC.utcHour)
    const utcDay = Number(trigger.fieldValues.day_of_week?.[0] ?? defaultAnchorUTC.utcDay)
    const {localHour, localMinute, localDay} = utcToLocalAnchor(utcDay, utcHour, isBrowser)
    const displayValue = formatLocalTime(localHour, localMinute)
    // Sort 24 UTC hours by their local-time equivalent (hour*60 + minute) so
    // the picker reads top-to-bottom in the user's clock order even when
    // their offset includes minutes (IST, NPT, Newfoundland, etc.).
    const entries = HOUR_UTC_OPTIONS.map(utcHourStr => {
      const u = Number(utcHourStr)
      const {localHour: lh, localMinute: lm} = utcToLocalAnchor(utcDay, u, isBrowser)
      return {utcHour: u, localHour: lh, localMinute: lm, sortKey: lh * 60 + lm, label: formatLocalTime(lh, lm)}
    }).sort((a, b) => a.sortKey - b.sortKey)
    return (
      <ActionMenu key="hour_utc">
        <ActionMenu.Button size="small" className={styles.filterButton} aria-label={`Schedule hour: ${displayValue}`}>
          {displayValue}
        </ActionMenu.Button>
        <ActionMenu.Overlay maxHeight="xsmall">
          <ActionList selectionVariant="single">
            {entries.map(entry => (
              <ActionList.Item
                key={entry.utcHour}
                selected={entry.utcHour === utcHour}
                onSelect={() => {
                  // Pin the user's currently-displayed local day so the
                  // weekday selection sticks across hour changes; UTC day
                  // may shift if the new local hour crosses midnight UTC.
                  const next = localToUTCAnchor(localDay, entry.localHour, entry.localMinute)
                  onChange(
                    selectedTriggers.map(t => {
                      if (t.name !== trigger.name) return t
                      const nextFieldValues: Record<string, string[]> = {
                        ...t.fieldValues,
                        hour_utc: [String(next.utcHour)],
                      }
                      // day_of_week is only meaningful for weekly schedules.
                      // For daily, hourly etc. we leave it cleared so the
                      // submitted shape doesn't carry a phantom anchor.
                      if (intervalType === 'weekly') {
                        nextFieldValues.day_of_week = [String(next.utcDay)]
                      }
                      return {...t, fieldValues: nextFieldValues}
                    }),
                  )
                }}
              >
                {entry.label}
              </ActionList.Item>
            ))}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    )
  }

  /**
   * Renders the day-of-week picker (Monday-first) for the interval trigger.
   * Stored as UTC day; displays the local day derived from the current
   * (UTC day, UTC hour) pair. Picking a day pins the displayed local hour
   * and recomputes the UTC anchor.
   */
  const renderDayDropdown = (trigger: SelectedTrigger) => {
    const utcHour = Number(trigger.fieldValues.hour_utc?.[0] ?? defaultAnchorUTC.utcHour)
    const utcDay = Number(trigger.fieldValues.day_of_week?.[0] ?? defaultAnchorUTC.utcDay)
    const {localHour, localMinute, localDay} = utcToLocalAnchor(utcDay, utcHour, isBrowser)
    const displayValue = DAY_OF_WEEK_LABELS[String(localDay)] ?? String(localDay)
    return (
      <ActionMenu key="day_of_week">
        <ActionMenu.Button
          size="small"
          className={styles.filterButton}
          aria-label={`Schedule day of week: ${displayValue}`}
        >
          {displayValue}
        </ActionMenu.Button>
        <ActionMenu.Overlay maxHeight="xsmall">
          <ActionList selectionVariant="single">
            {DAY_OF_WEEK_OPTIONS.map(localDayStr => {
              const ld = Number(localDayStr)
              return (
                <ActionList.Item
                  key={localDayStr}
                  selected={ld === localDay}
                  onSelect={() => {
                    const next = localToUTCAnchor(ld, localHour, localMinute)
                    onChange(
                      selectedTriggers.map(t =>
                        t.name === trigger.name
                          ? {
                              ...t,
                              fieldValues: {
                                ...t.fieldValues,
                                hour_utc: [String(next.utcHour)],
                                day_of_week: [String(next.utcDay)],
                              },
                            }
                          : t,
                      ),
                    )
                  }}
                >
                  {DAY_OF_WEEK_LABELS[localDayStr] ?? localDayStr}
                </ActionList.Item>
              )
            })}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    )
  }

  /** Renders a tag-based text input for free-text list fields (e.g. workflow names, paths). */
  const renderTagInput = (trigger: SelectedTrigger, field: TriggerField) => {
    const currentValues = trigger.fieldValues[field.name] ?? []
    const triggerDef = triggers.find(t => t.name === trigger.name)
    const label = triggerDef?.field_labels?.[field.name] ?? field.name
    const placeholder = `Enter ${label.toLowerCase()}`
    const requiredHint = 'At least one entry is required'
    const stateKey = `${trigger.name}:${field.name}`
    const showRequired = field.required && currentValues.length === 0
    const hintId = `${labelId}-${stateKey}-hint`

    // Initialize rows when this trigger's field is first rendered (useful for when we add the ability to edit via the form in the future)
    if (!filterRows[stateKey]) {
      const initialRows =
        currentValues.length > 0 ? currentValues.map(v => ({id: genRowId(), value: v})) : [{id: genRowId(), value: ''}]
      setFilterRows(prev => ({...prev, [stateKey]: initialRows}))
    }

    const rows = filterRows[stateKey] ?? [{id: genRowId(), value: ''}]

    const syncToParent = (updatedRows: Array<{id: string; value: string}>) => {
      const savedValues = [...new Set(updatedRows.map(r => r.value.trim()).filter(v => v !== ''))]
      updateFieldValue(trigger.name, field.name, savedValues)
    }

    const updateRow = (id: string, newValue: string) => {
      const currentRows = filterRows[stateKey] ?? [{id: genRowId(), value: ''}]
      const updated = currentRows.map(r => (r.id === id ? {id: r.id, value: newValue} : r))
      setFilterRows(prev => ({...prev, [stateKey]: updated}))
      syncToParent(updated)
    }

    const commitRow = (id: string, newValue: string) => {
      const currentRows = filterRows[stateKey] ?? [{id: genRowId(), value: ''}]
      const updated = currentRows.map(r => (r.id === id ? {id: r.id, value: newValue} : r))
      setFilterRows(prev => ({...prev, [stateKey]: updated}))
      syncToParent(updated)
    }

    const removeRow = (id: string) => {
      const currentRows = filterRows[stateKey] ?? [{id: genRowId(), value: ''}]
      let updated: Array<{id: string; value: string}>
      if (currentRows.length <= 1) {
        const firstRow = currentRows[0]
        updated = [{id: firstRow ? firstRow.id : genRowId(), value: ''}]
      } else {
        updated = currentRows.filter(r => r.id !== id)
      }
      setFilterRows(prev => ({...prev, [stateKey]: updated}))
      syncToParent(updated)
    }

    const addRow = () => {
      setFilterRows(prev => {
        const currentRows = prev[stateKey] ?? [{id: genRowId(), value: ''}]
        return {...prev, [stateKey]: [...currentRows, {id: genRowId(), value: ''}]}
      })
    }

    const handleRowKeyDown = (rowId: string) => (e: React.KeyboardEvent<HTMLInputElement>) => {
      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
      if (e.key === 'Enter') {
        e.preventDefault()
        commitRow(rowId, (e.target as HTMLInputElement).value)
        addFilterButtonRef.current.get(stateKey)?.focus()
      }
    }

    return (
      <div key={field.name} className={styles.fieldSection}>
        <span className={styles.fieldLabel}>
          {label}
          {field.required ? (
            <>
              <span aria-hidden="true" className={styles.requiredMark}>
                *
              </span>
              <span className="sr-only">required</span>
            </>
          ) : null}
        </span>
        {field.description ? <MarkdownRenderer markdown={field.description} className={styles.fieldHint} /> : null}
        {showRequired && (
          <span id={hintId} className="sr-only">
            {requiredHint}
          </span>
        )}
        {rows.map((row, index) => {
          const isOnlyRow = rows.length === 1
          const isSaved = currentValues.includes(row.value.trim()) && row.value.trim() !== ''
          const showXButton = !isOnlyRow || isSaved
          const ariaLabel = isOnlyRow
            ? `Clear ${label.toLowerCase()}`
            : row.value.trim()
              ? `Remove ${row.value.trim()}`
              : `Remove ${label.toLowerCase()} entry`
          return (
            <div key={row.id} className={styles.inputRow}>
              <TextInput
                ref={el => {
                  if (el) {
                    tagInputRef.current.set(row.id, el)
                  } else {
                    tagInputRef.current.delete(row.id)
                  }
                }}
                aria-label={rows.length > 1 ? `${label} ${index + 1}` : label}
                aria-describedby={showRequired && index === 0 ? hintId : undefined}
                placeholder={placeholder}
                block
                value={row.value}
                onChange={e => updateRow(row.id, e.target.value)}
                onKeyDown={handleRowKeyDown(row.id)}
                onBlur={() => {
                  commitRow(row.id, row.value)
                }}
                autoFocus={index === rows.length - 1 && row.value === '' && rows.length > 1}
              />
              {showXButton && (
                <IconButton
                  icon={XIcon}
                  variant="invisible"
                  aria-label={ariaLabel}
                  onMouseDown={e => e.preventDefault()}
                  onClick={() => {
                    removeRow(row.id)
                    requestAnimationFrame(() => {
                      if (isOnlyRow) {
                        tagInputRef.current.get(row.id)?.focus()
                      } else {
                        addFilterButtonRef.current.get(stateKey)?.focus()
                      }
                    })
                  }}
                />
              )}
            </div>
          )
        })}
        <Button
          ref={el => {
            if (el) {
              addFilterButtonRef.current.set(stateKey, el)
            } else {
              addFilterButtonRef.current.delete(stateKey)
            }
          }}
          size="small"
          leadingVisual={PlusIcon}
          className={styles.addFilterButton}
          onClick={addRow}
        >
          {`Add ${label.toLowerCase()}`}
        </Button>
      </div>
    )
  }

  /** Renders a single text input for the trigger query field. */
  const renderQueryInput = (trigger: SelectedTrigger, field: TriggerField) => {
    const currentValues = trigger.fieldValues[field.name] ?? []
    const value = currentValues[0] ?? ''
    const triggerDef = triggers.find(t => t.name === trigger.name)
    const label = triggerDef?.field_labels?.[field.name] ?? field.name
    const showClear = value !== ''

    return (
      <div key={field.name} className={styles.fieldSection}>
        <span className={styles.fieldLabel}>
          {label}
          {field.required ? (
            <>
              <span aria-hidden="true" className={styles.requiredMark}>
                *
              </span>
              <span className="sr-only">required</span>
            </>
          ) : null}
        </span>
        {field.description ? <MarkdownRenderer markdown={field.description} className={styles.fieldHint} /> : null}
        <div className={styles.inputRow}>
          <TextInput
            ref={el => {
              if (el) {
                queryInputRef.current.set(trigger.name, el)
              } else {
                queryInputRef.current.delete(trigger.name)
              }
            }}
            aria-label={label}
            placeholder="e.g. label:bug"
            block
            value={value}
            onChange={e => updateFieldValue(trigger.name, field.name, e.target.value ? [e.target.value] : [])}
          />
          {showClear && (
            <IconButton
              icon={XIcon}
              variant="invisible"
              aria-label={`Clear ${label.toLowerCase()}`}
              onClick={() => {
                updateFieldValue(trigger.name, field.name, [])
                requestAnimationFrame(() => queryInputRef.current.get(trigger.name)?.focus())
              }}
            />
          )}
        </div>
      </div>
    )
  }

  /** Renders the description line with inline option dropdowns for a trigger card. */
  const renderTriggerBody = (trigger: SelectedTrigger, definition: Trigger) => {
    const shouldHideOptions = definition.fields
      .filter((f): f is TriggerField & {options: string[]} => !!f.options && f.options.length > 0)
      .every(f => f.options.length === 1)
    const optionFields = shouldHideOptions ? [] : definition.fields.filter(f => f.options && f.options.length > 0)
    const freeTextFields = definition.fields.filter(f => !f.options || f.options.length === 0)
    const queryFields = freeTextFields.filter(f => f.name === 'query')
    const tagFields = freeTextFields.filter(f => f.name !== 'query')

    if (trigger.name === 'interval') {
      const intervalType = trigger.fieldValues.types?.[0]
      return (
        <span className={styles.descriptionLine}>
          <span className={styles.cardDescription}>Runs</span>
          {optionFields.map(field => renderOptionsDropdown(trigger, field))}
          {isAnchorFieldVisible('hour_utc', intervalType) && (
            <>
              <span className={styles.cardDescription}>at</span>
              {renderHourDropdown(trigger)}
            </>
          )}
          {isAnchorFieldVisible('day_of_week', intervalType) && (
            <>
              <span className={styles.cardDescription}>on</span>
              {renderDayDropdown(trigger)}
            </>
          )}
        </span>
      )
    }

    return (
      <>
        <span className={styles.descriptionLine}>
          <span className={styles.cardDescription}>{renderMarkdownLinks(definition.description)}</span>
          {optionFields.map(field => renderOptionsDropdown(trigger, field))}
        </span>
        {queryFields.map(field => renderQueryInput(trigger, field))}
        {tagFields.map(field => renderTagInput(trigger, field))}
      </>
    )
  }

  return (
    <PickerSection
      label="Triggers"
      caption="Select which events cause this automation to run."
      menu={triggerMenu}
      hasItems={selectedTriggers.length > 0}
      footer={footer}
      emptyStateFooter={
        <div className={styles.emptyStateFooter}>
          <InfoIcon size={16} className={styles.emptyStateFooterIcon} />
          <span>With no triggers, this automation can only be run manually.</span>
        </div>
      }
    >
      {selectedTriggers.map(trigger => {
        const definition = triggers.find(d => d.name === trigger.name)
        if (!definition) return null
        const iconColor = TRIGGER_ICON_COLOR_MAP[trigger.name]
        const iconStyle = iconColor ? {color: iconColor} : undefined
        const TriggerIconComponent = TRIGGER_ICON_MAP[trigger.name]
        return (
          <PickerCard
            key={trigger.name}
            icon={TriggerIconComponent ? <TriggerIconComponent size={16} /> : undefined}
            iconStyle={iconStyle}
            title={definition.title}
            removeLabel={`Remove ${definition.title}`}
            onRemove={() => removeTrigger(trigger.name)}
          >
            {renderTriggerBody(trigger, definition)}
          </PickerCard>
        )
      })}
    </PickerSection>
  )
}
