import {useSearchParams} from '@github-ui/use-navigate'
import {useState, useMemo, useCallback} from 'react'
import type {UITask} from '../types/task'
import type {FilterQuery} from '@github-ui/filter-core'
import type {Icon} from '@primer/octicons-react'
import {parsePageNumber} from '../utils/url-helpers'
import {
  SessionStatusFilterProvider,
  SessionCreatorFilterProvider,
  SessionSortFilterProvider,
  SessionDetailedStatusFilterProvider,
  SessionAgentFilterProvider,
  SessionTypeFilterProvider,
} from '../utils/session-filter-providers'
import type {AgentInfo} from '../types/session'
import type {SubAgent} from '../types/agent'
import type {ActiveTab} from '../types/filter-types'
import type {SortDirection, ParsedFilters} from '../utils/filter-utils'
import {DEFAULT_FILTER_QUERY, ME_ALIAS, parseFilterQuery, buildFilterQuery} from '../utils/filter-utils'
import {useCreatorOptions, useAgentOptions} from './use-filter-options'
import {
  readFiltersFromSearchParams,
  writeFiltersToSearchParams,
  writeLegacyFilterParams,
} from '../utils/session-filter-url'

export function useTaskFilters(
  tasks: UITask[],
  activeTab: ActiveTab,
  isFetching: boolean,
  currentUserLogin?: string,
  apiAgents?: AgentInfo[],
  customAgents?: SubAgent[],
  apiCreators?: Array<{id: number; login?: string}>,
  hideAuthorFilter?: boolean,
  useQSyntax?: boolean,
) {
  const [searchParams, setSearchParams] = useSearchParams()

  // --- Resolve @me helper ---
  const resolveMe = useCallback(
    (value: string) => (value === ME_ALIAS && currentUserLogin ? currentUserLogin : value),
    [currentUserLogin],
  )

  // --- Read filter state from unified ?q= param (with legacy fallback) ---
  const parsedFromUrl = useMemo(
    () => readFiltersFromSearchParams(searchParams, currentUserLogin),
    [searchParams, currentUserLogin],
  )

  const sortDirection: SortDirection = parsedFromUrl.sort
  const selectedCreators = parsedFromUrl.creators
  const excludedCreators = parsedFromUrl.excludedCreators
  const selectedAgents = parsedFromUrl.agents
  const selectedTypes = parsedFromUrl.types
  const selectedStatuses = parsedFromUrl.detailedStatuses
  const searchQuery = parsedFromUrl.freeText

  // --- Canonical filter string built from URL params ---

  const canonicalFilterValue = useMemo(
    () =>
      buildFilterQuery(
        activeTab,
        selectedCreators,
        sortDirection,
        searchQuery,
        selectedStatuses,
        selectedAgents,
        currentUserLogin,
        excludedCreators,
        selectedTypes,
      ),
    [
      activeTab,
      selectedCreators,
      sortDirection,
      searchQuery,
      selectedStatuses,
      selectedAgents,
      currentUserLogin,
      excludedCreators,
      selectedTypes,
    ],
  )

  // Sync local filter value when canonical (URL-derived) value changes.
  // This follows React's "adjusting state from props" pattern:
  // https://react.dev/reference/react/useState#storing-information-from-previous-renders
  const [filterValue, setFilterValue] = useState(canonicalFilterValue)
  const [prevCanonical, setPrevCanonical] = useState(canonicalFilterValue)

  if (canonicalFilterValue !== prevCanonical) {
    setPrevCanonical(canonicalFilterValue)
    setFilterValue(canonicalFilterValue)
  }

  // --- Derive filter options & build filter providers ---

  const creatorOptions = useCreatorOptions(apiCreators, currentUserLogin)
  const agentOptions = useAgentOptions(apiAgents, customAgents)

  // Exclude already-selected agents from the suggestion list so users
  // can't pick the same agent twice from the filter bar dropdown.
  const unselectedAgentOptions = useMemo(
    () => agentOptions.filter(option => !selectedAgents.includes(option.value)),
    [agentOptions, selectedAgents],
  )

  const filterProviders = useMemo(
    () => [
      new SessionStatusFilterProvider(),
      new SessionDetailedStatusFilterProvider(activeTab),
      new SessionCreatorFilterProvider({currentUserLogin, showAtMe: true}, {hiddenFromSuggestions: hideAuthorFilter}),
      new SessionTypeFilterProvider(),
      new SessionAgentFilterProvider(
        unselectedAgentOptions.map(option => ({key: option.value, label: option.label, icon: option.icon as Icon})),
      ),
      new SessionSortFilterProvider(),
    ],
    [unselectedAgentOptions, activeTab, hideAuthorFilter, currentUserLogin],
  )

  // --- URL update helpers ---

  const applyFilters = useCallback(
    (parsed: ParsedFilters) => {
      setSearchParams(
        prev => {
          const resolved: ParsedFilters = {
            ...parsed,
            creators: parsed.creators.map(resolveMe),
            excludedCreators: parsed.excludedCreators.map(resolveMe),
          }
          return useQSyntax
            ? writeFiltersToSearchParams(resolved, prev, currentUserLogin)
            : writeLegacyFilterParams(resolved, prev, currentUserLogin)
        },
        {preventAutofocus: true},
      )
    },
    [setSearchParams, resolveMe, currentUserLogin, useQSyntax],
  )

  const currentFilters = useCallback(
    (overrides: Partial<ParsedFilters> = {}): ParsedFilters => ({
      status: activeTab,
      detailedStatuses: selectedStatuses,
      creators: selectedCreators,
      excludedCreators,
      agents: selectedAgents,
      types: selectedTypes,
      sort: sortDirection,
      freeText: searchQuery,
      ...overrides,
    }),
    [
      activeTab,
      selectedStatuses,
      selectedCreators,
      excludedCreators,
      selectedAgents,
      selectedTypes,
      sortDirection,
      searchQuery,
    ],
  )

  // --- Filter bar callbacks ---

  const handleFilterChange = useCallback((value: string) => {
    setFilterValue(value)
  }, [])

  const handleFilterSubmit = useCallback(
    (request: FilterQuery) => {
      const raw = request.raw.trim()
      const parsed = raw ? parseFilterQuery(raw) : parseFilterQuery('')
      parsed.creators = parsed.creators.map(resolveMe)
      parsed.excludedCreators = parsed.excludedCreators.map(resolveMe)
      // The Filter component renders display names (e.g. "Copilot") but
      // we store slugs (e.g. "copilot-developer") in URL params. Resolve
      // display names back to slugs so both paths stay consistent.
      parsed.agents = parsed.agents.map(agent => {
        const match = agentOptions.find(option => option.label === agent || option.value === agent)
        return match?.value ?? agent
      })
      setFilterValue(
        buildFilterQuery(
          parsed.status,
          parsed.creators,
          parsed.sort,
          parsed.freeText,
          parsed.detailedStatuses,
          parsed.agents,
          currentUserLogin,
          parsed.excludedCreators,
          parsed.types,
        ),
      )
      applyFilters(parsed)
    },
    [applyFilters, resolveMe, currentUserLogin, agentOptions],
  )

  // Context-aware default: include author:@me when viewing own sessions
  const isCreatedByMe = currentUserLogin
    ? selectedCreators.length === 1 && selectedCreators[0] === currentUserLogin
    : false
  const defaultFilterQuery = isCreatedByMe ? `${DEFAULT_FILTER_QUERY} author:${ME_ALIAS}` : DEFAULT_FILTER_QUERY

  const isNonDefault = canonicalFilterValue !== defaultFilterQuery

  const handleResetToDefault = useCallback(() => {
    setFilterValue(defaultFilterQuery)
    applyFilters(parseFilterQuery(defaultFilterQuery))
  }, [applyFilters, defaultFilterQuery])

  // --- Tab click handler ---

  const handleTabClick = useCallback(
    (tab: ActiveTab) => {
      const parsed = currentFilters({status: tab, detailedStatuses: []})
      setFilterValue(
        buildFilterQuery(
          tab,
          parsed.creators,
          parsed.sort,
          parsed.freeText,
          [],
          parsed.agents,
          currentUserLogin,
          parsed.excludedCreators,
          parsed.types,
        ),
      )
      applyFilters(parsed)
    },
    [currentFilters, applyFilters, currentUserLogin],
  )

  // --- Dropdown change handlers ---

  const handleStatusChange = useCallback(
    (statuses: string[]) => applyFilters(currentFilters({detailedStatuses: statuses})),
    [currentFilters, applyFilters],
  )

  const handleSortChange = useCallback(
    (direction: SortDirection) => applyFilters(currentFilters({sort: direction})),
    [currentFilters, applyFilters],
  )

  const handleCreatorChange = useCallback(
    (creators: string[]) => applyFilters(currentFilters({creators})),
    [currentFilters, applyFilters],
  )

  const handleAgentChange = useCallback(
    (agents: string[]) => applyFilters(currentFilters({agents})),
    [currentFilters, applyFilters],
  )

  const handleTypeChange = useCallback(
    (types: string[]) => applyFilters(currentFilters({types})),
    [currentFilters, applyFilters],
  )

  // --- Navigation detection ---
  // Track URL param changes to show skeleton loaders during transitions
  const currentPage = parsePageNumber(searchParams.get('page'))
  const currentQ = searchParams.get('q')
  const searchParamsKey = searchParams.toString()
  const [prevPage, setPrevPage] = useState(currentPage)
  const [prevTab, setPrevTab] = useState(activeTab)
  const [prevQ, setPrevQ] = useState(currentQ)
  const [prevParamsKey, setPrevParamsKey] = useState(searchParamsKey)

  // In q= mode, track q/page/tab changes. In legacy mode, track any param change.
  const isNavigating = useQSyntax
    ? prevPage !== currentPage || prevTab !== activeTab || prevQ !== currentQ
    : prevParamsKey !== searchParamsKey || prevTab !== activeTab

  if (!isFetching && isNavigating) {
    setPrevPage(currentPage)
    setPrevTab(activeTab)
    setPrevQ(currentQ)
    setPrevParamsKey(searchParamsKey)
  }

  // --- Server-side filtering: tasks come pre-filtered from API ---
  // No client-side filtering needed — API handles tab, status, author, agent, sort, search

  const hasActiveFilters =
    searchQuery !== '' ||
    sortDirection !== 'newest' ||
    selectedCreators.length > 0 ||
    excludedCreators.length > 0 ||
    selectedAgents.length > 0 ||
    selectedTypes.length > 0 ||
    selectedStatuses.length > 0

  return {
    // Filter bar state
    filterValue,
    filterProviders,
    isNonDefault,

    // Dropdown state
    sortDirection,
    creatorOptions,
    selectedCreators,
    selectedStatuses,
    agentOptions,
    selectedAgents,
    selectedTypes,

    // Handlers
    handleFilterChange,
    handleFilterSubmit,
    handleResetToDefault,
    handleTabClick,
    handleSortChange,
    handleCreatorChange,
    handleStatusChange,
    handleAgentChange,
    handleTypeChange,

    // Navigation
    isNavigating,
    hasActiveFilters,
  }
}
