import type {UITask} from '@github-ui/agent-sessions/types/task'
import type {AgentInfo} from '@github-ui/agent-sessions/types/session'
import type {SubAgent} from '@github-ui/agent-sessions/types/agent'
import {Filter} from '@github-ui/filter'
import {IconButton} from '@primer/react'
import {XCircleFillIcon} from '@primer/octicons-react'
import {useMemo} from 'react'
import {TaskListItem} from '@github-ui/agent-sessions/components/task-list/TaskListItem'
import {TaskListLayout} from '@github-ui/agent-sessions/components/task-list/TaskListLayout'
import {getEmptyState} from './get-empty-state'
import type {AgentAccessState} from './get-agent-access-state'
import {useCurrentRepository} from '@github-ui/current-repository'
import styles from './RepoTaskList.module.css'
import type {ActiveTab} from '@github-ui/agent-sessions/types/filter-types'
import {RepoTaskListHeader} from './filters/RepoTaskListHeader'
import {useTaskFilters} from '@github-ui/agent-sessions/hooks/use-task-filters'
import {useTaskCreators} from '@github-ui/agent-sessions/hooks/use-task-creators'

interface RepoTaskListProps {
  tasks: UITask[]
  isError: boolean
  isLoading: boolean
  isFetching: boolean
  isPRLoading?: boolean
  activeTab: ActiveTab
  hasNextPage: boolean
  openCount?: number
  closedCount?: number
  currentUserId?: number
  currentUserLogin?: string
  accessState: AgentAccessState
  dataUpdatedAt?: number
  filtersEnabled?: boolean
  hideTabs?: boolean
  isFilteredByCurrentUser?: boolean
  excludeAuthorFilter?: string | null
  // Agent data: powers the group-based sidebar filter (when filtersEnabled is off)
  // and the filter bar's agent dropdown (when filtersEnabled is on)
  agents?: AgentInfo[]
  isLoadingAgents?: boolean
  selectedGroups?: string[]
  onAgentFilterChange?: (groups: string[]) => void
  customAgents?: SubAgent[]
}

export function RepoTaskList({
  tasks,
  isError,
  isLoading,
  isFetching,
  isPRLoading,
  activeTab,
  hasNextPage,
  openCount,
  closedCount,
  currentUserId,
  currentUserLogin,
  accessState,
  dataUpdatedAt,
  filtersEnabled = false,
  hideTabs = false,
  isFilteredByCurrentUser = false,
  excludeAuthorFilter,
  agents,
  isLoadingAgents,
  selectedGroups,
  onAgentFilterChange,
  customAgents,
}: RepoTaskListProps) {
  const repo = useCurrentRepository()
  const nwo = `${repo.ownerLogin}/${repo.name}`

  // Fetch task creators from CMC for the author filter dropdown.
  const {data: apiCreators} = useTaskCreators(repo.ownerLogin, repo.name, filtersEnabled)

  const {
    filterValue,
    filterProviders,
    isNonDefault,
    handleFilterChange,
    handleFilterSubmit,
    handleResetToDefault,
    handleTabClick,
    sortDirection,
    handleSortChange,
    creatorOptions,
    selectedCreators,
    handleCreatorChange,
    selectedStatuses,
    handleStatusChange,
    agentOptions,
    selectedAgents,
    handleAgentChange,
    selectedTypes,
    handleTypeChange,
    isNavigating,
    hasActiveFilters,
  } = useTaskFilters(
    tasks,
    activeTab,
    isFetching,
    currentUserLogin,
    agents,
    customAgents,
    apiCreators,
    isFilteredByCurrentUser,
    filtersEnabled,
  )

  // In "Created by me" mode the author filter provider is kept (for @me token
  // highlighting) but hidden from the search dropdown via hiddenFromSuggestions.
  const effectiveProviders = filterProviders

  // Client-side filtering for excluded authors (API doesn't support this).
  // Applied AFTER useTaskFilters so filter option derivation uses the full task list.
  const displayTasks = useMemo(() => {
    if (!excludeAuthorFilter) return tasks
    const excluded = new Set(excludeAuthorFilter.split(',').map(login => login.trim().toLowerCase()))
    return tasks.filter(task => !task.creator_login || !excluded.has(task.creator_login.toLowerCase()))
  }, [tasks, excludeAuthorFilter])

  const {heading: emptyHeading, description: emptyDescription} = getEmptyState({
    openCount,
    closedCount,
    activeTab,
    accessState,
  })

  const showSkeletonLoaders = (isFetching && isNavigating) || isLoading || (isFetching && displayTasks.length === 0)
  const showingFilteredEmpty = displayTasks.length === 0 && hasActiveFilters

  const clearButton = isNonDefault ? (
    <IconButton
      aria-label="Reset filters"
      icon={XCircleFillIcon}
      variant="invisible"
      size="small"
      onClick={handleResetToDefault}
    />
  ) : null

  return (
    <div>
      {filtersEnabled && (
        <div className={styles.filterBarContainer}>
          <Filter
            id="session-filter"
            label="Filter sessions"
            variant="input"
            providers={effectiveProviders}
            filterValue={filterValue}
            onChange={handleFilterChange}
            onSubmit={handleFilterSubmit}
            showClearButton={false}
            trailingVisual={clearButton}
          />
        </div>
      )}
      <TaskListLayout
        tasks={displayTasks}
        isError={isError}
        isLoading={isLoading}
        showSkeletonLoaders={showSkeletonLoaders}
        hasNextPage={hasNextPage}
        header={
          <RepoTaskListHeader
            activeTab={activeTab}
            setActiveTab={handleTabClick}
            openCount={openCount}
            closedCount={closedCount}
            showSkeletonLoaders={showSkeletonLoaders}
            filtersEnabled={filtersEnabled}
            hideTabs={hideTabs}
            owner={repo.ownerLogin}
            repo={repo.name}
            sortDirection={filtersEnabled ? sortDirection : undefined}
            onSortChange={filtersEnabled ? handleSortChange : undefined}
            creatorOptions={filtersEnabled && !isFilteredByCurrentUser ? creatorOptions : undefined}
            selectedCreators={filtersEnabled && !isFilteredByCurrentUser ? selectedCreators : undefined}
            onCreatorChange={filtersEnabled && !isFilteredByCurrentUser ? handleCreatorChange : undefined}
            selectedStatuses={filtersEnabled ? selectedStatuses : undefined}
            onStatusChange={filtersEnabled ? handleStatusChange : undefined}
            agentOptions={filtersEnabled ? agentOptions : undefined}
            selectedAgents={filtersEnabled ? selectedAgents : undefined}
            onAgentChange={filtersEnabled ? handleAgentChange : undefined}
            selectedTypes={filtersEnabled ? selectedTypes : undefined}
            onTypeChange={filtersEnabled ? handleTypeChange : undefined}
            agents={agents}
            isLoadingAgents={isLoadingAgents}
            selectedGroups={selectedGroups}
            onAgentFilterChange={onAgentFilterChange}
          />
        }
        emptyHeading={showingFilteredEmpty ? 'No sessions match your filters' : emptyHeading}
        emptyDescription={showingFilteredEmpty ? 'Try adjusting your search or filters.' : emptyDescription}
        errorText="Unable to load tasks, try again later."
        renderItem={task => (
          <TaskListItem
            key={task.clientGeneratedId ?? task.id ?? task.resource_id}
            task={task}
            nwo={nwo}
            currentUserId={currentUserId}
            isPRLoading={isPRLoading}
            dataUpdatedAt={dataUpdatedAt}
          />
        )}
      />
    </div>
  )
}
