import type {Icon} from '@primer/octicons-react'
import {SelectFilterProvider, BaseUserFilterProvider} from '@github-ui/filter-core/providers'
import {FilterValueType} from '@github-ui/filter-core'
import type {FilterKey, FilterSuggestion, SuppliedFilterProviderOptions} from '@github-ui/filter-core'
import type {UserFilterParams} from '@github-ui/filter-core/providers'
import {
  AgentIcon,
  AlertIcon,
  ArchiveIcon,
  PersonIcon,
  CopilotIcon,
  SortDescIcon,
  IterationsIcon,
  CheckCircleIcon,
  ClockIcon,
  DotFillIcon,
  StopIcon,
  SkipIcon,
  GitMergeIcon,
  GitPullRequestClosedIcon,
  TerminalIcon,
  VscodeIcon,
} from '@primer/octicons-react'
import type {ActiveTab} from '../types/filter-types'

export class SessionStatusFilterProvider extends SelectFilterProvider {
  constructor(options?: SuppliedFilterProviderOptions) {
    const filterKey: FilterKey = {
      displayName: 'Is',
      key: 'is',
      priority: 1,
      icon: AgentIcon,
      description: 'Filter by session status',
    }
    const filterValues: FilterSuggestion[] = [
      {value: 'open', displayName: 'Active', type: FilterValueType.Value, priority: 1, icon: AgentIcon},
      {value: 'closed', displayName: 'Completed', type: FilterValueType.Value, priority: 2, icon: ArchiveIcon},
    ]
    super(filterKey, filterValues, {
      ...options,
      strictMatching: true,
      filterTypes: {
        inclusive: true,
        exclusive: false,
        valueless: false,
        hasValue: false,
        multiValue: false,
        multiKey: false,
      },
    })
  }
}

export class SessionCreatorFilterProvider extends BaseUserFilterProvider {
  #hiddenFromSuggestions: boolean

  constructor(
    filterParams?: UserFilterParams,
    options?: SuppliedFilterProviderOptions & {hiddenFromSuggestions?: boolean},
  ) {
    const filterKey: FilterKey = {
      displayName: 'Author',
      key: 'author',
      priority: 3,
      icon: PersonIcon,
      description: 'Filter by author',
    }
    const {hiddenFromSuggestions: hidden, ...providerOptions} = options ?? {}
    super(filterKey, filterParams, {
      ...providerOptions,
      filterTypes: {
        inclusive: true,
        exclusive: true,
        valueless: false,
        hasValue: false,
        multiValue: true,
        multiKey: true,
      },
    })
    this.#hiddenFromSuggestions = hidden ?? false
  }

  getfilterKeys(): FilterKey[] {
    if (this.#hiddenFromSuggestions) return []
    return [
      {
        key: this.key,
        aliases: this.aliases,
        displayName: this.displayName,
        description: this.description,
        priority: this.priority,
        icon: this.icon,
      },
    ]
  }
}

