const OPEN_STATUS_SUGGESTIONS: FilterSuggestion[] = [
  {value: 'in_progress', displayName: 'In progress', type: FilterValueType.Value, priority: 1, icon: IterationsIcon},
  {value: 'queued', displayName: 'Queued', type: FilterValueType.Value, priority: 2, icon: ClockIcon},
  {value: 'idle', displayName: 'Idle', type: FilterValueType.Value, priority: 3, icon: DotFillIcon},
  {
    value: 'needs_attention',
    displayName: 'Needs attention',
    type: FilterValueType.Value,
    priority: 4,
    icon: AlertIcon,
  },
  {value: 'failed', displayName: 'Failed', type: FilterValueType.Value, priority: 5, icon: StopIcon},
  {value: 'completed', displayName: 'Completed', type: FilterValueType.Value, priority: 6, icon: CheckCircleIcon},
  {value: 'cancelled', displayName: 'Cancelled', type: FilterValueType.Value, priority: 7, icon: SkipIcon},
  {value: 'timed_out', displayName: 'Timed out', type: FilterValueType.Value, priority: 8, icon: StopIcon},
]

const CLOSED_STATUS_SUGGESTIONS: FilterSuggestion[] = [
  {value: 'merged', displayName: 'Merged', type: FilterValueType.Value, priority: 1, icon: GitMergeIcon},
  {value: 'closed', displayName: 'Closed', type: FilterValueType.Value, priority: 2, icon: GitPullRequestClosedIcon},
  {value: 'archived', displayName: 'Archived', type: FilterValueType.Value, priority: 3, icon: ArchiveIcon},
]

export class SessionDetailedStatusFilterProvider extends SelectFilterProvider {
  constructor(activeTab: ActiveTab, options?: SuppliedFilterProviderOptions) {
    const filterKey: FilterKey = {
      displayName: 'Status',
      key: 'status',
      priority: 2,
      icon: AgentIcon,
      description: 'Filter by detailed session status',
    }

    let filterValues: FilterSuggestion[]
    if (activeTab === 'open') {
      filterValues = [...OPEN_STATUS_SUGGESTIONS]
    } else if (activeTab === 'closed') {
      filterValues = [...CLOSED_STATUS_SUGGESTIONS]
    } else {
      filterValues = [...OPEN_STATUS_SUGGESTIONS, ...CLOSED_STATUS_SUGGESTIONS]
    }

    super(filterKey, filterValues, {
      ...options,
      strictMatching: true,
      filterTypes: {
        inclusive: true,
        exclusive: false,
        valueless: false,
        hasValue: false,
        multiValue: true,
        multiKey: true,
      },
    })
  }
}

export interface AgentOption {
  key: string
  label: string
  icon?: Icon
}

export class SessionAgentFilterProvider extends SelectFilterProvider {
  constructor(agents: AgentOption[], options?: SuppliedFilterProviderOptions) {
    const filterKey: FilterKey = {
      displayName: 'Agent',
      key: 'agent',
      priority: 4,
      icon: CopilotIcon,
      description: 'Filter by agent',
    }
    const filterValues: FilterSuggestion[] = agents.map((agent, index) => ({
      value: agent.key,
      displayName: agent.label,
      type: FilterValueType.Value,
      priority: index + 1,
      icon: agent.icon ?? CopilotIcon,
    }))
    super(filterKey, filterValues, {
      ...options,
      strictMatching: false,
      filterTypes: {
        inclusive: true,
        exclusive: false,
        valueless: false,
        hasValue: false,
        multiValue: true,
        multiKey: true,
      },
    })
  }
}

