import {ConfirmationDialog} from '@primer/react'
import {useCurrentRepository} from '@github-ui/current-repository'
import {useDeleteAutomation} from '../../hooks/use-delete-automation'

interface DeleteAutomationDialogProps {
  automationId: string
  onClose: () => void
  onDeleted: () => void
}

export function DeleteAutomationDialog({automationId, onClose, onDeleted}: DeleteAutomationDialogProps) {
  const repository = useCurrentRepository()
  const {mutateAsync: deleteAutomation, isPending: isDeleting} = useDeleteAutomation({
    owner: repository.ownerLogin,
    repo: repository.name,
    automationId,
  })

  return (
    <ConfirmationDialog
      title="Delete this automation?"
      onClose={async gesture => {
        if (gesture === 'confirm') {
          await deleteAutomation()
          onDeleted()
        }
        onClose()
      }}
      confirmButtonContent={isDeleting ? 'Deleting…' : 'Delete'}
      confirmButtonType="danger"
    >
      This cannot be undone. Existing sessions will complete.
    </ConfirmationDialog>
  )
}
