import {getEnv} from '@github-ui/client-env'
import {CopilotAuthTokenProvider} from '@github-ui/copilot-auth-token'
import {makeCAPIRequest} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useMutation} from '@github-ui/react-query'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {
  buildSuggestToolsResponseSchema,
  buildSuggestToolsSystemPrompt,
  buildSuggestToolsUserPrompt,
  parseSuggestToolsResponse,
  type SuggestionContext,
} from './suggest-tools-helpers'
import {isSelectableToolGroup, type ToolGroup} from './tool-definitions'

const COPILOT_API_DEFAULT_BASE = 'https://api.githubcopilot.com'
const COPILOT_INTEGRATION_ID = 'copilot-embedded-experience'
const SUGGEST_TOOLS_MODEL = 'gpt-4o-mini'
const MAX_PROMPT_LENGTH = 50_000

export type SuggestToolsResultKind = 'idle' | 'success' | 'empty' | 'error'

export interface SuggestToolsResult {
  kind: SuggestToolsResultKind
  /** Number of valid IDs the model returned (after filtering against catalog). */
  returnedCount?: number
  /** Number of IDs that were appended to the selection (excludes already-selected). */
  addedCount?: number
  /** Number of IDs the model returned that were not in the catalog. */
  filteredOutCount?: number
  /** When kind === 'empty', why the result was empty. */
  emptyReason?: 'model_empty' | 'all_filtered' | 'all_already_selected'
  /** When kind === 'error', a human-readable description. */
  errorMessage?: string
}

export interface UseSuggestToolsArgs {
  toolGroups: ToolGroup[]
  selectedTools: string[]
  onApply: (newToolIds: string[]) => void
}

export interface UseSuggestToolsValue {
  suggest: (context: SuggestionContext) => void
  isPending: boolean
  lastResult: SuggestToolsResult
}

interface MutationInput {
  context: SuggestionContext
  selectedSnapshot: string[]
}

/**
 * Calls the small-model CAPI endpoint to suggest tools for the current
 * automation. Mirrors `commits/hooks/use-copilot-commit-recap.ts`.
 */
export function useSuggestTools({toolGroups, selectedTools, onApply}: UseSuggestToolsArgs): UseSuggestToolsValue {
  const abortControllerRef = useRef<AbortController | null>(null)
  const [lastResult, setLastResult] = useState<SuggestToolsResult>({kind: 'idle'})

  const selectableGroups = useMemo(
    () => toolGroups.filter(group => isSelectableToolGroup(group.id) && group.tools.length > 0),
    [toolGroups],
  )

  const knownToolIds = useMemo(
    () => selectableGroups.flatMap(group => group.tools.map(tool => tool.id)),
    [selectableGroups],
  )

  useEffect(() => () => abortControllerRef.current?.abort(), [])

  const {mutate, isPending} = useMutation<SuggestToolsResult, Error, MutationInput>({
    mutationFn: async ({context, selectedSnapshot}) => {
      const startedAt = Date.now()
      const controller = new AbortController()
      abortControllerRef.current = controller

      const systemPrompt = buildSuggestToolsSystemPrompt(selectableGroups)
      const userPrompt = buildSuggestToolsUserPrompt(context)
      if (systemPrompt.length + userPrompt.length > MAX_PROMPT_LENGTH) {
        throw new SuggestToolsValidationError('Prompt is too long. Please shorten the description or prompt.')
      }

      const authToken = await new CopilotAuthTokenProvider([]).getAuthToken()

      const response = await makeCAPIRequest({
        basePath: getEnv().copilotApiOverrideUrl || COPILOT_API_DEFAULT_BASE,
        path: '/chat/completions',
        method: 'POST',
        streamingResponse: false,
        authToken,
        integrationId: COPILOT_INTEGRATION_ID,
        signal: controller.signal,
        body: {
          messages: [
            {role: 'system', content: systemPrompt},
            {role: 'user', content: userPrompt},
          ],
          model: SUGGEST_TOOLS_MODEL,
          stream: false,
          response_format: buildSuggestToolsResponseSchema(knownToolIds),
        },
      })

      // makeCAPIRequest catches AbortError and returns a FailedAPIResult;
      // detect that here so onError's AbortError guard stays meaningful.
      if (controller.signal.aborted) {
        throw new DOMException('Aborted', 'AbortError')
      }

      if (!response.ok) {
        const errorMessage = 'error' in response ? response.error : 'CAPI request failed'
        throw new SuggestToolsHttpError(response.status, errorMessage)
      }

      const data = await response.json()
      const content = data?.choices?.[0]?.message?.content
      if (content === undefined || content === null) {
        throw new Error('No content in model response')
      }

      const {validIds, filteredOutCount} = parseSuggestToolsResponse(content, knownToolIds)
      const selectedSet = new Set(selectedSnapshot)
      const addedIds = validIds.filter(id => !selectedSet.has(id))
      const latencyMs = Date.now() - startedAt

      if (addedIds.length > 0) {
        onApply(addedIds)
        sendEvent('automation_suggest_tools.success', {
          returnedCount: validIds.length,
          addedCount: addedIds.length,
          filteredOutCount,
          latencyMs,
          knownCatalogSize: knownToolIds.length,
          promptLength: context.prompt.length,
        })
        return {kind: 'success', returnedCount: validIds.length, addedCount: addedIds.length, filteredOutCount}
      }

      const reason: SuggestToolsResult['emptyReason'] =
        validIds.length === 0 && filteredOutCount === 0
          ? 'model_empty'
          : validIds.length === 0
            ? 'all_filtered'
            : 'all_already_selected'
      sendEvent('automation_suggest_tools.empty', {reason, filteredOutCount, latencyMs})
      return {kind: 'empty', emptyReason: reason, returnedCount: validIds.length, filteredOutCount}
    },
    onSuccess: result => setLastResult(result),
    onError: error => {
      if (error.name === 'AbortError') return
      const isClientValidation = error instanceof SuggestToolsValidationError
      const httpStatus = error instanceof SuggestToolsHttpError ? error.status : undefined
      sendEvent('automation_suggest_tools.error', {
        httpStatus,
        errorKind: error instanceof SuggestToolsHttpError ? 'http' : isClientValidation ? 'validation' : 'client',
      })
      setLastResult({
        kind: 'error',
        errorMessage: isClientValidation ? error.message : "Couldn't suggest tools. Please try again.",
      })
    },
  })

  const suggest = useCallback(
    (context: SuggestionContext) => {
      sendEvent('automation_suggest_tools.clicked', {
        promptLength: context.prompt.length,
        nameLength: context.name.length,
        descriptionLength: context.description.length,
        alreadySelectedCount: selectedTools.length,
        catalogSize: knownToolIds.length,
      })
      mutate({context, selectedSnapshot: [...selectedTools]})
    },
    [mutate, selectedTools, knownToolIds.length],
  )

  return {suggest, isPending, lastResult}
}

class SuggestToolsHttpError extends Error {
  readonly status: number

  constructor(status: number, message: string) {
    super(message)
    this.name = 'SuggestToolsHttpError'
    this.status = status
  }
}

class SuggestToolsValidationError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'SuggestToolsValidationError'
  }
}
