import {ConfirmationDialog} from '@primer/react'
import {useCurrentRepository} from '@github-ui/current-repository'
import {useSetAutomationDisabled} from '../../hooks/use-set-automation-disabled'
import {isActiveLimitReachedError} from './ActiveLimitReachedBanner'

interface ToggleAutomationDialogProps {
  automationId: string
  disable: boolean
  onClose: () => void
  onActiveLimitReached: () => void
  onAutomationDisabled?: () => void
}

export function ToggleAutomationDialog({
  automationId,
  disable,
  onClose,
  onActiveLimitReached,
  onAutomationDisabled,
}: ToggleAutomationDialogProps) {
  const repository = useCurrentRepository()
  const {mutateAsync: setDisabled, isPending} = useSetAutomationDisabled({
    owner: repository.ownerLogin,
    repo: repository.name,
    automationId,
  })

  return (
    <ConfirmationDialog
      title={disable ? 'Disable this automation?' : 'Enable this automation?'}
      onClose={async gesture => {
        if (gesture !== 'confirm') {
          onClose()
          return
        }
        try {
          await setDisabled(disable)
          if (disable) onAutomationDisabled?.()
          onClose()
        } catch (err) {
          if (isActiveLimitReachedError(err)) {
            onActiveLimitReached()
          }
          onClose()
        }
      }}
      confirmButtonType="primary"
      confirmButtonLoading={isPending}
    >
      {disable
        ? 'This automation will no longer run. Sessions already in flight will continue.'
        : 'This automation will run when triggered.'}
    </ConfirmationDialog>
  )
}
