import {AlertIcon} from '@primer/octicons-react'
import {SimpleListView} from '@github-ui/simple-list-view'
import {SimpleListHeader} from '@github-ui/simple-list-view/SimpleListHeader'
import {SimpleListItem} from '@github-ui/simple-list-view/SimpleListItem'
import {ListItemsSkeletonLoader} from '@github-ui/agent-sessions/components/task-list/ListParts'
import {AutomationListItem} from './AutomationListItem'
import {SkeletonText} from '@primer/react/experimental'
import {Banner, Label} from '@primer/react'
import {clsx} from 'clsx'
import {useCallback, useState} from 'react'
import pluralize from 'pluralize'
import type {Automation} from '../../types/automations-payload'

import styles from '@github-ui/agent-sessions/components/task-list/TaskListLayout.module.css'
import automationStyles from './AutomationsView.module.css'

interface AutomationsListProps {
  automations: Automation[]
  isError: boolean
  isLoading: boolean
  onActiveLimitReached: () => void
  onAutomationDisabled?: () => void
}

export function AutomationsList({
  automations,
  isError,
  isLoading,
  onActiveLimitReached,
  onAutomationDisabled,
}: AutomationsListProps) {
  const showSkeletonLoaders = isLoading
  const [runError, setRunError] = useState<string | null>(null)

  const handleRunError = useCallback((message: string) => {
    setRunError(message)
  }, [])

  const handleRunStart = useCallback(() => {
    setRunError(null)
  }, [])

  const header = (
    <span className={styles.runCount}>
      {showSkeletonLoaders ? (
        <SkeletonText size="bodyMedium" className={styles.runCountSkeleton} />
      ) : (
        <>
          {`${automations.length.toLocaleString()} ${pluralize('automation', automations.length)}`}
          <Label className="ml-2">Only you can see these</Label>
        </>
      )}
    </span>
  )

  return (
    <div className={styles.list}>
      {runError && (
        <div className={automationStyles.bannerWrapper}>
          <Banner variant="critical" title="Run failed" onDismiss={() => setRunError(null)}>
            {runError}
          </Banner>
        </div>
      )}
      <SimpleListView>
        <SimpleListHeader className={styles.header}>
          <SimpleListHeader.Metadata>{header}</SimpleListHeader.Metadata>
        </SimpleListHeader>
        <SimpleListView.Items className={clsx(styles.listContainer, styles.items)}>
          {isError ? (
            <SimpleListItem className={styles.emptyItem}>
              <AlertIcon className={styles.noItemsIcon} />
              <p className={styles.emptyTitle}>Unable to load automations, try again later.</p>
            </SimpleListItem>
          ) : showSkeletonLoaders ? (
            <ListItemsSkeletonLoader />
          ) : (
            automations.map(automation => (
              <AutomationListItem
                key={automation.id}
                automation={automation}
                onActiveLimitReached={onActiveLimitReached}
                onAutomationDisabled={onAutomationDisabled}
                onRunError={handleRunError}
                onRunStart={handleRunStart}
              />
            ))
          )}
        </SimpleListView.Items>
      </SimpleListView>
    </div>
  )
}
