import {setTitle} from '@github-ui/document-metadata'
import {useCurrentRepository} from '@github-ui/current-repository'
import {useParams} from '@github-ui/react-router'
import {ActionMenu, ActionList, Banner, Button, Heading, IconButton, Label} from '@primer/react'
import {
  ChevronLeftIcon,
  GearIcon,
  BookIcon,
  KebabHorizontalIcon,
  TrashIcon,
  PlayIcon,
  PauseIcon,
  WorkflowIcon,
} from '@primer/octicons-react'
import {useNavigate, useSearchParams} from '@github-ui/use-navigate'
import {useEffect, useState} from 'react'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {automationDetailRoute} from '../../routes/automations-route'
import {TaskListItem} from '@github-ui/agent-sessions/components/task-list/TaskListItem'
import {TaskListLayout} from '@github-ui/agent-sessions/components/task-list/TaskListLayout'
import {generateTaskPathForRepo} from '@github-ui/agent-sessions/utils/generate-task-path'
import pluralize from 'pluralize'
import {useAutomationTasks} from '../../hooks/use-automation-tasks'
import {useAutomation} from '../../hooks/use-automation'
import {DeleteAutomationDialog} from './DeleteAutomationDialog'
import {ToggleAutomationDialog} from './ToggleAutomationDialog'
import {ConvertToWorkflowDialog} from './ConvertToWorkflowDialog'
import {RunAutomationDialog} from './RunAutomationDialog'
import {useTriggers} from '@github-ui/automation-form/use-triggers'
import {useRunAutomationAction} from '../../hooks/use-run-automation-action'
import {EMPTY_REPO_NOTICE} from '@github-ui/automation-form'

import styles from './RepoAgentsView.module.css'
import automationStyles from './AutomationsView.module.css'
import taskListStyles from '@github-ui/agent-sessions/components/task-list/TaskListLayout.module.css'

/**
 * Detail view for a single automation.
 * Shows the automation name with a back arrow inline with the title.
 */
export function AutomationDetailView() {
  const {data: payload} = useRouteQuery(automationDetailRoute, 'mainQuery')
  const repository = useCurrentRepository()
  const navigate = useNavigate()
  const {automationID} = useParams<{automationID: string}>()
  const {automation} = useAutomation({
    owner: repository.ownerLogin,
    repo: repository.name,
    automationId: automationID,
    initialData: payload.automation,
  })
  const backHref = `/${repository.ownerLogin}/${repository.name}/agents/automations`
  const {tasks, isError, isLoading} = useAutomationTasks({
    automationId: automationID,
    initialData: payload.tasks,
    repoId: repository.databaseId,
  })
  const nwo = `${repository.ownerLogin}/${repository.name}`
  const {triggers} = useTriggers()
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
  const [isToggleDialogOpen, setIsToggleDialogOpen] = useState(false)
  const [isConvertDialogOpen, setIsConvertDialogOpen] = useState(false)
  const [runError, setRunError] = useState<string | null>(null)
  const [searchParams, setSearchParams] = useSearchParams()
  const [runSuccess, setRunSuccess] = useState(() => searchParams.get('run') === 'success')
  const {isRunDialogOpen, setIsRunDialogOpen, handleRunClick, isPending, runAutomation, error, resetError} =
    useRunAutomationAction({
      owner: repository.ownerLogin,
      repo: repository.name,
      automation,
      triggerDefinitions: triggers,
      onError: setRunError,
      onSuccess: () => setRunSuccess(true),
      disabled: repository.isEmpty,
    })

  useEffect(() => {
    if (automation) {
      setTitle(`${automation.name} · Automations · ${repository.nameWithOwner}`)
    }
  }, [automation, repository.nameWithOwner])

  const header = (
    <span className={taskListStyles.runCount}>
      {`${tasks.length.toLocaleString()} ${pluralize('session', tasks.length)}`}
    </span>
  )

  return (
    <div className={styles.container} data-hpc>
      <div className={styles.content}>
        <header className={automationStyles.headerRow}>
          <div className={styles.header}>
            <IconButton
              as="a"
              href={backHref}
              icon={ChevronLeftIcon}
              variant="invisible"
              /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
              aria-label="Back to Automations"
              onClick={(e: React.MouseEvent) => {
                e.preventDefault()
                navigate(backHref)
              }}
            />
            <div className={automationStyles.titleGroup}>
              <Heading as="h2" className={styles.title}>
                {automation?.name}
              </Heading>
              {automation?.disabled && (
                <Label variant="secondary" className={automationStyles.titleLabel}>
                  Disabled
                </Label>
              )}
            </div>
          </div>
          <div className={automationStyles.headerActions}>
            <Button
              as="a"
              href={`${backHref}/${encodeURIComponent(automationID ?? '')}/edit`}
              leadingVisual={GearIcon}
              onClick={(e: React.MouseEvent) => {
                // Let modifier-clicks and middle-clicks open the link in a new tab natively
                // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
                if (e.metaKey || e.ctrlKey || e.shiftKey || e.button === 1) return
                e.preventDefault()
                navigate(`${backHref}/${encodeURIComponent(automationID ?? '')}/edit`)
              }}
            >
              Edit
            </Button>
            <Button
              leadingVisual={PlayIcon}
              onClick={() => {
                setRunError(null)
                setRunSuccess(false)
                if (searchParams.has('run')) {
                  const next = new URLSearchParams(searchParams)
                  next.delete('run')
                  setSearchParams(next, {replace: true})
                }
                handleRunClick()
              }}
              disabled={(isPending && !isRunDialogOpen) || repository.isEmpty}
            >
              {isPending && !isRunDialogOpen ? 'Running...' : 'Run now'}
            </Button>
            <ActionMenu>
              <ActionMenu.Anchor>
                <IconButton icon={KebabHorizontalIcon} aria-label="More options" />
              </ActionMenu.Anchor>
              <ActionMenu.Overlay width="auto">
                <ActionList>
                  <ActionList.LinkItem href="https://gh.io/cca-automations-docs">
                    <ActionList.LeadingVisual>
                      <BookIcon />
                    </ActionList.LeadingVisual>
                    View documentation
                  </ActionList.LinkItem>
                  {automation?.disabled ? (
                    <ActionList.Item disabled={repository.isEmpty} onSelect={() => setIsToggleDialogOpen(true)}>
                      <ActionList.LeadingVisual>
                        <PlayIcon />
                      </ActionList.LeadingVisual>
                      Enable automation
                    </ActionList.Item>
                  ) : (
                    <ActionList.Item onSelect={() => setIsToggleDialogOpen(true)}>
                      <ActionList.LeadingVisual>
                        <PauseIcon />
                      </ActionList.LeadingVisual>
                      Disable automation
                    </ActionList.Item>
                  )}
                  <ActionList.Item onSelect={() => setIsConvertDialogOpen(true)}>
                    <ActionList.LeadingVisual>
                      <WorkflowIcon />
                    </ActionList.LeadingVisual>
                    Convert to agentic workflow
                  </ActionList.Item>
                  <ActionList.Divider />
                  {automationID && (
                    <ActionList.Item variant="danger" onSelect={() => setIsDeleteDialogOpen(true)}>
                      <ActionList.LeadingVisual>
                        <TrashIcon />
                      </ActionList.LeadingVisual>
                      Delete
                    </ActionList.Item>
                  )}
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          </div>
          {isDeleteDialogOpen && automationID && (
            <DeleteAutomationDialog
              automationId={automationID}
              onDeleted={() => navigate(backHref)}
              onClose={() => setIsDeleteDialogOpen(false)}
            />
          )}
          {isToggleDialogOpen && automationID && (
            <ToggleAutomationDialog
              automationId={automationID}
              disable={!automation?.disabled}
              onClose={() => setIsToggleDialogOpen(false)}
              onActiveLimitReached={() => navigate(backHref, {state: {activeLimitReached: true}})}
            />
          )}
          {isConvertDialogOpen && automationID && (
            <ConvertToWorkflowDialog automationId={automationID} onClose={() => setIsConvertDialogOpen(false)} />
          )}
          {isRunDialogOpen && automation && (
            <RunAutomationDialog
              automation={automation}
              triggerDefinitions={triggers}
              runAutomation={runAutomation}
              isPending={isPending}
              error={error}
              resetError={resetError}
              onClose={() => setIsRunDialogOpen(false)}
              onSuccess={() => {
                setIsRunDialogOpen(false)
                setRunSuccess(true)
              }}
            />
          )}
        </header>
        {repository.isEmpty && (
          <Banner variant="warning" title={EMPTY_REPO_NOTICE.title}>
            {EMPTY_REPO_NOTICE.description}
          </Banner>
        )}
        {runSuccess && (
          <Banner
            variant="success"
            title="Run started"
            onDismiss={() => {
              setRunSuccess(false)
              if (searchParams.has('run')) {
                const next = new URLSearchParams(searchParams)
                next.delete('run')
                setSearchParams(next, {replace: true})
              }
            }}
          >
            The automation run has been queued. It will appear in the sessions list shortly.
          </Banner>
        )}
        {runError && (
          <Banner variant="critical" title="Run failed" onDismiss={() => setRunError(null)}>
            {runError}
          </Banner>
        )}
        <TaskListLayout
          tasks={tasks}
          isError={isError}
          isLoading={isLoading}
          showSkeletonLoaders={isLoading}
          hasNextPage={false}
          header={header}
          emptyHeading="No tasks for this automation yet"
          emptyDescription="Tasks triggered by this automation will appear here."
          errorText="Unable to load tasks, try again later."
          renderItem={listTask => (
            <TaskListItem
              key={listTask.clientGeneratedId ?? listTask.id ?? listTask.resource_id}
              task={listTask}
              nwo={nwo}
              getTaskUrl={(task, repoNwo, params) => {
                const base = generateTaskPathForRepo({
                  repositoryNwo: repoNwo,
                  taskId: task.id ?? undefined,
                  pullRequestNumber: task.pull?.number,
                })
                if (!base) return undefined
                params.set('automation', automation?.id ?? '')
                const query = params.toString()
                return query ? `${base}?${query}` : base
              }}
            />
          )}
        />
      </div>
    </div>
  )
}
