import type {UITask} from '@github-ui/agent-sessions/types/task'
import {TaskListItem} from '@github-ui/agent-sessions/components/task-list/TaskListItem'
import {TaskTitle} from '@github-ui/agent-sessions/components/task-list/TaskTitle'
import {TaskDescription} from '@github-ui/agent-sessions/components/task-list/TaskDescription'
import {TaskListLayout} from '@github-ui/agent-sessions/components/task-list/TaskListLayout'
import {useCurrentRepository} from '@github-ui/current-repository'
import styles from '@github-ui/agent-sessions/components/task-list/TaskListLayout.module.css'
import {SkeletonText} from '@primer/react/experimental'
import pluralize from 'pluralize'

interface CodeReviewTaskListProps {
  tasks: UITask[]
  isError: boolean
  isLoading: boolean
  isFetching: boolean
  isPRLoading?: boolean
  hasNextPage: boolean
  openCount?: number
  closedCount?: number
  dataUpdatedAt?: number
}

export function CodeReviewTaskList({
  tasks,
  isError,
  isLoading,
  isFetching,
  isPRLoading,
  hasNextPage,
  openCount,
  closedCount,
  dataUpdatedAt,
}: CodeReviewTaskListProps) {
  const repo = useCurrentRepository()
  const nwo = `${repo.ownerLogin}/${repo.name}`

  const totalCount = (openCount ?? 0) + (closedCount ?? 0)
  const showSkeletonLoaders = isLoading || !!isPRLoading || (isFetching && tasks.length === 0)

  const header = (
    <span className={styles.runCount}>
      {showSkeletonLoaders ? (
        <SkeletonText size="bodyMedium" className={styles.runCountSkeleton} />
      ) : (
        `${totalCount.toLocaleString()} ${pluralize('review', totalCount)}`
      )}
    </span>
  )

  return (
    <TaskListLayout
      tasks={tasks}
      isError={isError}
      isLoading={isLoading}
      showSkeletonLoaders={showSkeletonLoaders}
      hasNextPage={hasNextPage}
      header={header}
      emptyHeading="There are no code reviews yet"
      emptyDescription="Code reviews from Copilot will appear here."
      errorText="Unable to load code reviews, try again later."
      renderItem={listTask => (
        <TaskListItem
          key={listTask.clientGeneratedId ?? listTask.id ?? listTask.resource_id}
          task={listTask}
          nwo={nwo}
          renderTitle={(task, props) => (
            <TaskTitle task={task} {...props} title={task.pull?.title} prefix="Review of" />
          )}
          analyticsTarget="CODE_REVIEW_TASK"
          dataUpdatedAt={dataUpdatedAt}
          renderDescription={(task, props) => (
            <TaskDescription
              {...props}
              parts={[
                ...props.parts,
                task.pull && task.pull.comments > 0 ? (
                  <span key="comments">{pluralize('comment', task.pull.comments, true)}</span>
                ) : null,
              ]}
            />
          )}
        />
      )}
    />
  )
}
