import {useResolveAuthorIds} from '@github-ui/agent-sessions/hooks/use-resolve-author-ids'

interface CurrentUser {
  id: number
  login: string
}

// Declared outside the hook so React Query sees the same array reference
// across renders and doesn't re-trigger unnecessarily.
const EMPTY_CREATOR_IDS: number[] = []

/**
 * Resolves author logins from URL params to numeric creator IDs for the CMC API.
 * Handles "Created by me" shortcut, current-user instant resolution, and
 * assignees-endpoint-based resolution for external users (no 25-user cap).
 */
export function useResolvedCreatorIds({
  authorParams,
  isFilteredByCurrentUser,
  isCodeReviewMode,
  currentUser,
  repository,
}: {
  authorParams: string[]
  isFilteredByCurrentUser: boolean
  isCodeReviewMode: boolean
  currentUser?: CurrentUser | null
  repository: {ownerLogin: string; name: string}
}) {
  const hasAuthorFilter = authorParams.length > 0 && !authorParams.includes('*')

  // Logins that need resolution via the assignees endpoint (excludes current user
  // since we can resolve that instantly from the session).
  const loginsToResolve =
    hasAuthorFilter && !isFilteredByCurrentUser && !isCodeReviewMode
      ? authorParams.filter(login => login !== currentUser?.login)
      : undefined

  const {resolvedAuthorIds, isResolvingAuthors} = useResolveAuthorIds(
    repository.ownerLogin,
    repository.name,
    loginsToResolve && loginsToResolve.length > 0 ? loginsToResolve : undefined,
  )

  const resolvedCreatorIds: number[] | undefined = (() => {
    if (isFilteredByCurrentUser || isCodeReviewMode) {
      return currentUser?.id ? [currentUser.id] : undefined
    }
    if (!hasAuthorFilter) return undefined

    // Still resolving external logins — not ready yet
    if (loginsToResolve && loginsToResolve.length > 0 && isResolvingAuthors) {
      return undefined
    }

    const ids: number[] = []

    // Instantly resolve current user if they're in the author list
    if (authorParams.includes(currentUser?.login ?? '') && currentUser?.id) {
      ids.push(currentUser.id)
    }

    // Add IDs resolved via the assignees endpoint
    if (resolvedAuthorIds) {
      ids.push(...resolvedAuthorIds)
    }

    return ids.length > 0 ? ids : EMPTY_CREATOR_IDS
  })()

  // Author filter is "ready" when we don't need resolution or it's complete.
  const authorFilterReady = !hasAuthorFilter || isFilteredByCurrentUser || resolvedCreatorIds !== undefined

  return {resolvedCreatorIds, authorFilterReady}
}
