import {Banner} from '@primer/react'
import type {Ref} from 'react'
import {FetchCAPIError} from '@github-ui/agent-sessions/utils/fetch-capi'

export const ACTIVE_LIMIT_REACHED_CODE = 'active_limit_reached'
export const ACTIVE_AUTOMATIONS_LIMIT = 15

/** Location state set when create redirects to the list after auto-disabling a newly capped automation. */
export type AutomationsLocationState = {activeLimitReached?: boolean}

const TITLE = 'Active automation limit reached'
const DESCRIPTION = `You've reached the ${ACTIVE_AUTOMATIONS_LIMIT} active automation limit for this repository. Disable an active automation to enable this one.`

type ActiveLimitReachedBannerProps = {
  ref?: Ref<HTMLElement>
  onDismiss?: () => void
}

export function ActiveLimitReachedBanner({ref, onDismiss}: ActiveLimitReachedBannerProps) {
  return (
    <Banner ref={ref} tabIndex={-1} variant="warning" title={TITLE} description={DESCRIPTION} onDismiss={onDismiss} />
  )
}

export function isActiveLimitReachedError(error: unknown): boolean {
  return (
    error instanceof FetchCAPIError &&
    error.status === 422 &&
    (error.errors?.some(e => e.code === ACTIVE_LIMIT_REACHED_CODE) ?? false)
  )
}
