import {useMutation, useQueryClient} from '@github-ui/react-query'
import {fetchCAPI} from '@github-ui/agent-sessions/utils/fetch-capi'
import {automationQueryKey} from './use-automation'

interface UseSetAutomationDisabledArgs {
  owner: string
  repo: string
  automationId: string
}

export function useSetAutomationDisabled({owner, repo, automationId}: UseSetAutomationDisabledArgs) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationKey: ['setAutomationDisabled', owner, repo, automationId],
    mutationFn: async (disabled: boolean) => {
      if (!automationId) {
        throw new Error('automationId is required')
      }

      const response = await fetchCAPI({
        path: `/agents/repos/${owner}/${repo}/automations/${encodeURIComponent(automationId)}`,
        method: 'PATCH',
        body: {
          disabled,
        },
      })
      return response
    },
    onSuccess: () => {
      queryClient.invalidateQueries({queryKey: automationQueryKey(owner, repo, automationId)})
      queryClient.invalidateQueries({queryKey: ['automations', owner, repo]})
    },
  })
}
