import {clsx} from 'clsx'
import {ListViewSectionFilterLink} from '@github-ui/list-view/ListViewSectionFilterLink'
import type {AgentInfo} from '@github-ui/agent-sessions/types/session'
import type {ActiveTab} from '@github-ui/agent-sessions/types/filter-types'
import type {FilterOption, SortDirection} from '@github-ui/agent-sessions/utils/filter-utils'
import {FilterActionBar} from './FilterActionBar'
import {AgentFilterButton} from '../AgentFilterButton'
import styles from '../RepoTaskList.module.css'

interface RepoTaskListHeaderProps {
  activeTab: ActiveTab
  setActiveTab: (tab: ActiveTab) => void
  openCount?: number
  closedCount?: number
  showSkeletonLoaders: boolean
  filtersEnabled?: boolean
  hideTabs?: boolean
  owner: string
  repo: string
  // New filter props (only used when filtersEnabled is true)
  sortDirection?: SortDirection
  onSortChange?: (direction: SortDirection) => void
  creatorOptions?: FilterOption[]
  selectedCreators?: string[]
  onCreatorChange?: (creators: string[]) => void
  selectedStatuses?: string[]
  onStatusChange?: (statuses: string[]) => void
  agentOptions?: FilterOption[]
  selectedAgents?: string[]
  onAgentChange?: (agents: string[]) => void
  selectedTypes?: string[]
  onTypeChange?: (types: string[]) => void
  // Sidebar agent filter props (used when filtersEnabled is false)
  agents?: AgentInfo[]
  isLoadingAgents?: boolean
  selectedGroups?: string[]
  onAgentFilterChange?: (groups: string[]) => void
}

export function RepoTaskListHeader({
  activeTab,
  setActiveTab,
  openCount,
  closedCount,
  showSkeletonLoaders,
  filtersEnabled,
  hideTabs,
  owner,
  repo,
  sortDirection,
  onSortChange,
  creatorOptions,
  selectedCreators,
  onCreatorChange,
  selectedStatuses,
  onStatusChange,
  agentOptions,
  selectedAgents,
  onAgentChange,
  selectedTypes,
  onTypeChange,
  agents,
  isLoadingAgents,
  selectedGroups,
  onAgentFilterChange,
}: RepoTaskListHeaderProps) {
  if (hideTabs) {
    // When hideTabs is true (e.g. Needs Attention), only show the filter action bar if filters are enabled
    if (!filtersEnabled) return null
    return (
      <div className={styles.headerContainer}>
        <FilterActionBar
          activeTab={activeTab}
          owner={owner}
          repo={repo}
          sortDirection={sortDirection}
          onSortChange={onSortChange}
          creatorOptions={creatorOptions}
          selectedCreators={selectedCreators}
          onCreatorChange={onCreatorChange}
          selectedStatuses={selectedStatuses}
          onStatusChange={onStatusChange}
          agentOptions={agentOptions}
          selectedAgents={selectedAgents}
          onAgentChange={onAgentChange}
          selectedTypes={selectedTypes}
          onTypeChange={onTypeChange}
        />
      </div>
    )
  }

  if (!filtersEnabled) {
    return (
      <div className={styles.headerContainer}>
        <ul className={clsx(styles.tabsContainer, 'list-style-none')} aria-label="Filter by status">
          <li>
            <ListViewSectionFilterLink
              title="Active"
              isSelected={activeTab === 'open'}
              count={openCount?.toLocaleString()}
              isLoading={showSkeletonLoaders}
              href="#"
              onClick={e => {
                e.preventDefault()
                setActiveTab('open')
              }}
            />
          </li>
          <li>
            <ListViewSectionFilterLink
              title="Completed"
              isSelected={activeTab === 'closed'}
              count={closedCount?.toLocaleString()}
              isLoading={showSkeletonLoaders}
              href="#"
              onClick={e => {
                e.preventDefault()
                setActiveTab('closed')
              }}
            />
          </li>
        </ul>
        {onAgentFilterChange && (
          <div className={styles.filtersRight}>
            <AgentFilterButton
              agents={agents || []}
              selectedGroups={selectedGroups || []}
              onSelectionChange={onAgentFilterChange}
              isLoading={isLoadingAgents}
            />
          </div>
        )}
      </div>
    )
  }

  return (
    <div className={styles.headerContainer}>
      <ul className={clsx(styles.tabsContainer, 'list-style-none')} aria-label="Filter by status">
        <li>
          <ListViewSectionFilterLink
            title="Active"
            isSelected={activeTab === 'open'}
            count={openCount?.toLocaleString()}
            isLoading={showSkeletonLoaders}
            href="#"
            onClick={e => {
              e.preventDefault()
              setActiveTab('open')
            }}
          />
        </li>
        <li>
          <ListViewSectionFilterLink
            title="Completed"
            isSelected={activeTab === 'closed'}
            count={closedCount?.toLocaleString()}
            isLoading={showSkeletonLoaders}
            href="#"
            onClick={e => {
              e.preventDefault()
              setActiveTab('closed')
            }}
          />
        </li>
      </ul>
      <FilterActionBar
        activeTab={activeTab}
        owner={owner}
        repo={repo}
        sortDirection={sortDirection}
        onSortChange={onSortChange}
        creatorOptions={creatorOptions}
        selectedCreators={selectedCreators}
        onCreatorChange={onCreatorChange}
        selectedStatuses={selectedStatuses}
        onStatusChange={onStatusChange}
        agentOptions={agentOptions}
        selectedAgents={selectedAgents}
        onAgentChange={onAgentChange}
        selectedTypes={selectedTypes}
        onTypeChange={onTypeChange}
      />
    </div>
  )
}
