import {useMutation, useQueryClient} from '@github-ui/react-query'
import {fetchCAPI} from '@github-ui/agent-sessions/utils/fetch-capi'
import {buildTriggerObject} from '@github-ui/automation-form'
import type {AutomationFormData} from '@github-ui/automation-form'
import {automationQueryKey} from './use-automation'

interface UseUpdateAutomationArgs {
  owner: string
  repo: string
  automationId: string
}

export function useUpdateAutomation({owner, repo, automationId}: UseUpdateAutomationArgs) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationKey: ['updateAutomation', owner, repo, automationId],
    mutationFn: async (data: AutomationFormData) => {
      const triggers = buildTriggerObject(data.triggers)

      const response = await fetchCAPI({
        path: `/agents/repos/${owner}/${repo}/automations/${encodeURIComponent(automationId)}`,
        method: 'PATCH',
        body: {
          name: data.name,
          description: data.description,
          prompt: data.prompt,
          model: data.model,
          require_actor_write_permission: data.requireActorWritePermission,
          ...(triggers && {triggers}),
          ...(data.tools.length > 0 && {tools: data.tools}),
        },
      })
      return response
    },
    onSuccess: () => {
      queryClient.invalidateQueries({queryKey: automationQueryKey(owner, repo, automationId)})
      queryClient.invalidateQueries({queryKey: ['automations', owner, repo]})
    },
  })
}
