import {useMemo, useCallback, useEffect, useRef} from 'react'
import {QueryClient, useQueryClient} from '@github-ui/react-query'
import {useDebounce} from '@github-ui/use-debounce'
import {fetchCAPI} from '@github-ui/agent-sessions/utils/fetch-capi'
import {useCAPIQuery} from '@github-ui/agent-sessions/hooks/useCAPIQuery'
import type {OptimisticTask, UITask} from '@github-ui/agent-sessions/types/task'
import {parseLinkHeader} from '@github-ui/agent-sessions/utils/pagination-helpers'
import {usePullRequests} from '@github-ui/agent-sessions/hooks/usePullRequests'
import type {IdToPullRequestMap} from '@github-ui/agent-sessions/types/pull'
import {useAgentSessionsAlive} from '@github-ui/agent-sessions/hooks/use-agent-sessions-alive'
import type {AgentSessionAlivePayload} from '@github-ui/agent-sessions/hooks/use-agent-sessions-alive'
import type {APITask} from '@github-ui/agent-sessions/types/api-task'
import {
  sortTasksByDate,
  syncSingleTaskCachesFromList,
  transformAPITasksToUnhydrated,
} from '@github-ui/agent-sessions/utils/task-helpers'
import {repoTasksApiPathWithParams, type TasksQueryParams} from '@github-ui/agent-sessions/utils/api-url-helpers'

import {
  repoTasksQueryKey,
  REPO_TASKS_PAGE_SIZE,
  preventOptimisticOverflow,
  type FetchRepoTasksResponse,
  type TaskCounts,
} from '@github-ui/agent-sessions/hooks/repo-task-utils'
import {useSearchParams} from '@github-ui/use-navigate'
import {parsePageNumber} from '@github-ui/agent-sessions/utils/url-helpers'
import {getInteractiveRefetchInterval, hasInteractiveTasks} from '@github-ui/agent-sessions/agents/interactive-polling'

export const PAGE_SIZE = REPO_TASKS_PAGE_SIZE

interface UseRepoTasksOptions {
  owner: string
  repo: string
  /**
   * The repository ID. Used to filter alive events to only those for this repository.
   */
  repoId: number
  pollingInterval?: number | false
  /**
   * Numeric creator IDs to filter tasks by (supports multi-author via repeated creator_id params).
   */
  creatorIds?: number[]
  /**
   * Initial tasks data to seed the query, typically from the route payload.
   * These are raw API tasks that will be transformed to UnhydratedTask format.
   */
  initialData?: APITask[]
  /**
   * Initial pull request map to seed the pull requests query.
   */
  initialPullRequestsMap?: IdToPullRequestMap
  /**
   * Whether to fetch closed instead of open tasks (legacy — prefer `tab`).
   */
  fetchArchivedTasks?: boolean
  /**
   * Tab filter sent to API: 'open', 'closed', or undefined for all tasks.
   */
  tab?: 'open' | 'closed'
  /**
   * Optional task type filter (e.g., 'review' for code review tasks only).
   */
  taskType?: string
  /**
   * Optional agent IDs to filter tasks by agent.
   */
  agentIds?: number[]
  /**
   * Optional custom agent name to filter tasks by exact match.
   */
  customAgentName?: string
  enabled?: boolean
  /**
   * Optional detailed statuses to filter by (server-side).
   */
  statuses?: string[]
  /**
   * Optional sort direction: 'newest' or 'oldest' (server-side).
   */
  sort?: string
  /**
   * Optional free-text search query (server-side).
   */
  query?: string
  /**
   * Optional agent slugs to filter by (server-side).
   */
  agentSlugs?: string[]
}

/**
 * Fetches tasks for a specific repository from CAPI.
 * @param repoOwner - The owner of the repository (org or user login)
 * @param repo - The repository name
 * @param creatorIds - Optional user IDs to filter tasks by creator
 * @param queryClient - The query client used to access existing optimistic tasks
 * @param queryKey - The query key for accessing cached tasks
 * @returns a promise that resolves to a tuple of:
 *          - a combined, date-sorted list of unhydrated and optimistic tasks
 *          - a boolean indicating whether there are more pages of tasks to fetch
 *          - an object containing the counts of active and archived tasks
 */
async function fetchRepoTasks(
  repoOwner: string,
  repo: string,
  creatorIds: number[] | undefined,
  queryClient: QueryClient,
  queryKey: ReturnType<typeof repoTasksQueryKey>,
  page?: number,
  archived?: boolean,
  includeCounts?: boolean,
  taskType?: string,
  agentIds?: number[],
  statuses?: string[],
  sort?: string,
  query?: string,
  agentSlugs?: string[],
  tab?: 'open' | 'closed',
  customAgentName?: string,
): Promise<FetchRepoTasksResponse> {
  const params: TasksQueryParams = {
    creatorIds,
    page,
    archived,
    includeCounts,
    pageSize: PAGE_SIZE,
    type: taskType,
    agentIds,
    tab,
    statuses,
    sort,
    query,
    agentSlugs,
    customAgentName,
  }
  const path = repoTasksApiPathWithParams(repoOwner, repo, params)

  const response = await fetchCAPI({path})
  const data = await response.json()
  const apiTasks = data.tasks as APITask[]
  const serverTasks = transformAPITasksToUnhydrated(apiTasks)
  const hasNextPage = parseLinkHeader(response.headers?.get('Link'))

  // Get any remaining optimistic tasks from the cache (ones not yet replaced by onSuccess)
  const existingData = queryClient.getQueryData<FetchRepoTasksResponse>(queryKey)
  const existingTasks = existingData?.[0] || []
  const optimisticTasks = existingTasks.filter((task): task is OptimisticTask => !!task.isOptimistic)
  let taskCounts: TaskCounts | undefined
  if (includeCounts && typeof data.total_active_count === 'number' && typeof data.total_archived_count === 'number') {
    taskCounts = {
      open: data.total_active_count,
      closed: data.total_archived_count,
    }
  }

  const sorted = sortTasksByDate([...serverTasks, ...optimisticTasks])
  // When sort=oldest, reverse to preserve the server's ascending order
  // (sortTasksByDate always sorts newest-first for optimistic task merging)
  if (sort === 'oldest') sorted.reverse()

  return [sorted, hasNextPage ?? !!data.has_next_page, taskCounts]
}

/**
 * Hook for fetching tasks for a specific repository.
 */
export function useRepoTasks({
  owner,
  repo,
  repoId,
  pollingInterval = 3000,
  creatorIds,
  initialData,
  initialPullRequestsMap,
  fetchArchivedTasks,
  tab,
  taskType,
  agentIds,
  customAgentName,
  enabled = true,
  statuses,
  sort,
  query,
  agentSlugs,
}: UseRepoTasksOptions) {
  // For code review tasks, always fetch both active and completed tasks
  const isCodeReviewMode = taskType === 'review'
  if (isCodeReviewMode) {
    // eslint-disable-next-line react-hooks/immutability
    fetchArchivedTasks = undefined
  }

  // Track the taskType from the initial page load so we only use server-rendered
  // initialData when the current taskType matches what the server rendered
  const initialTaskTypeRef = useRef(taskType)

  const [searchParams] = useSearchParams()
  const currentPage = parsePageNumber(searchParams.get('page'))

  const queryClient = useQueryClient()
  const mappedInitialData = useMemo(
    () => (initialData ? transformAPITasksToUnhydrated(initialData) : undefined),
    [initialData],
  )

  const handleAliveUpdate = useCallback(
    (payload?: AgentSessionAlivePayload) => {
      // Only invalidate if the event is for this repository
      if (payload?.repo_id !== undefined && payload.repo_id !== repoId) {
        return
      }

      queryClient.invalidateQueries({
        queryKey: repoTasksQueryKey(
          owner,
          repo,
          creatorIds,
          currentPage,
          fetchArchivedTasks,
          taskType,
          agentIds,
          customAgentName,
          statuses,
          sort,
          query,
          agentSlugs,
        ),
      })
    },
    [
      queryClient,
      owner,
      repo,
      repoId,
      creatorIds,
      currentPage,
      fetchArchivedTasks,
      taskType,
      agentIds,
      customAgentName,
      statuses,
      sort,
      query,
      agentSlugs,
    ],
  )

  const debouncedHandleAliveUpdate = useDebounce(handleAliveUpdate, pollingInterval || 3000, {maxWait: 10000})

  useAgentSessionsAlive({
    onEvent: debouncedHandleAliveUpdate,
    enableCreateEvents: false,
    enableUpdateEvents: enabled,
    enableLogUpdates: false,
    enableTaskUpdates: enabled,
    enabled,
  })

  const queryKey = repoTasksQueryKey(
    owner,
    repo,
    creatorIds,
    currentPage,
    fetchArchivedTasks,
    taskType,
    agentIds,
    customAgentName,
    statuses,
    sort,
    query,
    agentSlugs,
  )

  const {
    data,
    dataUpdatedAt,
    isLoading: isLoadingSessions,
    isFetching,
    isError: isSessionError,
  } = useCAPIQuery({
    // eslint-disable-next-line @tanstack/query/exhaustive-deps
    queryKey,
    queryFn: () =>
      fetchRepoTasks(
        owner,
        repo,
        creatorIds,
        queryClient,
        queryKey,
        currentPage,
        fetchArchivedTasks,
        true,
        taskType,
        agentIds,
        statuses,
        sort,
        query,
        agentSlugs,
        tab,
        customAgentName,
      ),
    refetchInterval: ({state: {data: queryData}}) =>
      getInteractiveRefetchInterval(hasInteractiveTasks(queryData?.[0] ?? [])),
    // The Remote CLI behavior is best suited being as close to real-time as possible,
    // so fetching fresh data on refocus helps.
    refetchOnWindowFocus: true,
    enabled,
    // Only use initialData when page and archived state match what the server rendered,
    // and the current taskType matches the initial page load (server-rendered data is scoped to the initial tab)
    // otherwise incorrect data could be used when changing tabs
    initialData:
      currentPage === 1 &&
      !fetchArchivedTasks &&
      // eslint-disable-next-line react-hooks/refs
      taskType === initialTaskTypeRef.current &&
      !agentIds?.length &&
      mappedInitialData
        ? [mappedInitialData, false]
        : undefined,
  })

  const allTasks = useMemo(() => (Array.isArray(data?.[0]) ? data[0] : []), [data])
  const hasNextPage = !!data?.[1]

  // Propagate fresh `stale_at` values into any open single-task caches so the
  // detail view picks up updates from the list without waiting for its own poll.
  useEffect(() => {
    syncSingleTaskCachesFromList(queryClient, allTasks)
  }, [allTasks, queryClient])

  const {data: prMap = {}, isLoading: isLoadingPRs} = usePullRequests({
    tasks: allTasks,
    initialPullRequestsMap: fetchArchivedTasks || currentPage !== 1 ? undefined : initialPullRequestsMap,
    refetchOnMount: true,
  })

  // Hydrate tasks with pull request data, preserving optimistic tasks
  const tasks: UITask[] = useMemo(() => {
    if (!allTasks.length) return []

    const hydratedTasks = allTasks
      .map((task): UITask | null => {
        // Preserve optimistic tasks as-is (they don't have PR data yet)
        if (task.isOptimistic) {
          return task
        }

        if (!task.resource_id) return task

        const pull = prMap[task.resource_id]

        return {
          ...task,
          pull,
        }
      })
      .filter((task): task is UITask => task !== null)

    return preventOptimisticOverflow(hydratedTasks)
  }, [allTasks, prMap])
  const hasTasks = allTasks.length > 0
  const isLoadingPRData = isLoadingPRs && hasTasks

  // PR data loads in the background and hydrates tasks as it arrives
  const isLoading = isLoadingSessions
  // Only block the task list for task fetch errors. PR hydration errors should degrade
  // gracefully (tasks render without that metadata) rather than hiding the entire list.
  const isError = isSessionError
  const isFetchingData = isFetching

  return {
    tasks,
    queryKey,
    dataUpdatedAt,
    isLoading,
    isFetching: isFetchingData,
    isError,
    hasNextPage,
    counts: data?.[2],
    isPRLoading: isLoadingPRData,
  }
}
